'use strict';
const UI={view:'start',tab:'home',sel:null,comp:'table',tr:'market',trPos:'ALL',fixR:null,modal:null,match:null,msg:null,pick:null,mgr:'',boxSide:0,ldr:'pts'};

/* ===================== Small components ===================== */
const SHAPES=['M50 4 L92 20 V66 C92 94 72 110 50 120 C28 110 8 94 8 66 V20Z','M10 8 H90 V64 C90 94 70 110 50 120 C30 110 10 94 10 64Z','M50 4 L94 26 V78 L50 120 L6 78 V26Z'];
const LOGO=t=>(window.LOGOS||{})[t.short];
// on dark backgrounds (class 'dk') clubs with a dark logo use their white version
const LOGOW=t=>(window.LOGOS_DARK||{})[t.short]||LOGO(t);
function crest(t,cls=''){if(t&&t.nt&&window.NT_FLAGS&&NT_FLAGS[t.nt])return `<img class="crest ${cls}" src="${NT_FLAGS[t.nt]}" alt="" style="object-fit:contain">`;if(LOGO(t))return `<img class="crest logo ${cls}" src="${/\bdk\b/.test(cls)?LOGOW(t):LOGO(t)}" alt="">`;const d=SHAPES[t.id%3],tc=tcol(t),sz=t.short.length>3?26:31;
  return `<svg class="crest ${cls}" viewBox="0 0 100 124" aria-hidden="true"><path d="${d}" fill="${t.c1}" stroke="${t.c2}" stroke-width="5" stroke-linejoin="round"/><path d="${d}" transform="translate(9 11) scale(.82)" fill="none" stroke="${tc}" stroke-opacity=".45" stroke-width="2.4"/><path d="${d}" fill="url(#gl)"/><path d="M50 26 l3 6.4 7 .6-5.3 4.6 1.6 6.8L50 40.8l-6.3 3.6 1.6-6.8L40 33l7-.6z" fill="${tc}" opacity=".9"/><text x="50" y="84" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="900" font-size="${sz}" fill="${tc}" letter-spacing="1">${t.short}</text></svg>`;}
const mini=t=>LOGO(t)?`<img class="mini logo" src="${LOGO(t)}" alt="">`:`<span class="mini" style="background:${t.c1};color:${tcol(t)}">${t.short}</span>`;
// never show a portrait of a minor, even if a generated youngster shares a real player's name
const PH=p=>{const v=p&&p.age!=null&&p.age<18&&!(window.PH_OK||{})[p.phk||pname(p)]?null:(window.PHOTOS||{})[p.phk||pname(p)];return v?{sheet:window.SPRITES.p[v[0]],t:v[1]}:null;};
const spr=(o,alt)=>{const n=(window.SHEET_N||{})[o.sheet]||10;return `<span class="sp" role="img" aria-label="${esc(alt)}" style="background-image:url(${o.sheet});${n!==10?`background-size:${n*100}% ${n*100}%;`:''}background-position:${(o.t%n)*100/(n-1)}% ${Math.floor(o.t/n)*100/(n-1)}%"></span>`;};
const SIL=txt=>`<svg viewBox="0 0 100 100" aria-hidden="true"><rect width="100" height="100" fill="#eef0f3"/><circle cx="50" cy="37" r="17" fill="#c5cbd3"/><path d="M12 104C14 74 31 61 50 61S86 74 88 104Z" fill="#c5cbd3"/><text x="50" y="92" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="800" font-size="22" fill="#ffffff">${txt}</text></svg>`;
// players without a photo: a drawn silhouette in their club's jersey with the shirt number (no real face)
const JSIL=(p,txt)=>{const t=p&&p.tid!=null&&G&&G.teams[p.tid];return t?JSILt(t,txt):SIL(txt);};
const JSILt=(t,txt)=>{const c1=/^#[0-9a-f]{6}$/i.test(t.c1)?t.c1:'#1f3b73',tc=tcol(t),c2=/^#[0-9a-f]{6}$/i.test(t.c2)&&t.c2.toLowerCase()!==c1.toLowerCase()?t.c2:tc;
  return `<svg viewBox="0 0 100 100" aria-hidden="true"><rect width="100" height="100" fill="#eef0f3"/><rect width="100" height="100" fill="${c1}" opacity=".12"/><path d="M41 52h18v12H41z" fill="#b7bec8"/><ellipse cx="50" cy="35" rx="15" ry="17.5" fill="#c3c9d2"/><path d="M35 31c1-11 8-16 15-16s14 5 15 16c-3-5-8-7-15-7s-12 2-15 7z" fill="#a9b1bc"/><path d="M8 104c1-25 11-36 26-41l6 4c2 4 6 6 10 6s8-2 10-6l6-4c15 5 25 16 26 41z" fill="${c1}"/><path d="M34 63l6 4c2 4 6 6 10 6s8-2 10-6l6-4" fill="none" stroke="${c2}" stroke-width="3.2" stroke-linejoin="round"/><path d="M27 66c-2 9-2 21-1 38M73 66c2 9 2 21 1 38" stroke="${c2}" stroke-width="2.2" fill="none" opacity=".8"/><text x="50" y="95" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="900" font-size="21" fill="${tc}">${txt}</text></svg>`;};
const avatarIn=(p,txt)=>PH(p)?spr(PH(p),pname(p)):JSIL(p,txt);
const photoCredit=p=>'';
// stats of a player's main league: ABA for clubs that only play the ABA League
const mst=p=>{const t=p.tid!=null&&G.teams[p.tid];if(t&&t.dom==='CUP')return p.est||blank();return t&&(t.dom==='KLS'||t.dom==='BIH'||NLCFG[t.dom])?(p.kst||blank()):t&&t.dom?(p.dst||blank()):p.st;};
const ovc=o=>o>=85?'o1':o>=78?'o2':o>=70?'o3':o>=62?'o4':'o5';
const ovb=o=>`<span class="ovr ${ovc(o)}">${o}</span>`;
const form=f=>`<span class="fm">${f.map(x=>`<span class="${x}">${x}</span>`).join('')}</span>`;
const ecol=e=>e>=80?'var(--g)':e>=60?'var(--y)':'var(--r)';
const ebar=e=>`<span class="eb" title="Energy ${Math.round(e)}%${e<65?` \u00b7 injury risk \u00d7${fatigueRisk(e)}`:''}"><i style="width:${e}%;background:${ecol(e)}"></i></span>`;
// Long grey explainer paragraphs move out of the card body into a panel behind an "i" in the card header.
let infN=0;
function infSplit(body){if(typeof body!=='string'||!/class="(?:mut|cb mut|sec mut)"/.test(body))return [body,''];const out=[];
  const b=body.replace(/<(p|div) class="(?:mut|cb mut|sec mut)"[^>]*>((?:(?!<div|<p[ >])[\s\S])*?)<\/\1>/g,(m,tg,t,off)=>{
    if(/class="(neg|pos|pill|btn)|data-act|<input|<select|<button/.test(t))return m;
    if(t.replace(/<[^>]+>/g,'').length<110)return m;
    const pre=body.slice(Math.max(0,off-400),off),e=pre.lastIndexOf('class="empty"');if(e>=0&&pre.indexOf('</div>',e)<0)return m;
    out.push(t);return '';});
  if(!out.length)return [body,''];
  const b2=b.replace(/<div class="(?:sec|cb)"[^>]*>\s*<\/div>/g,'');
  if(!b2.replace(/<[^>]+>/g,'').trim()&&b2.indexOf('<svg')<0&&b2.indexOf('<img')<0&&b2.indexOf('<canvas')<0)return [body,''];
  return [b2,out.map(t=>`<p>${t}</p>`).join('')];}
const card=(title,body,link)=>{const [b,inf]=infSplit(body),id=inf?'inf'+(++infN):'';
  return `<section class="card"><div class="ch"><h3>${title}${inf?`<label class="inf" for="${id}" title="How this works">i</label>`:''}</h3>${link||''}</div>${inf?`<input type="checkbox" class="inf-c" id="${id}" aria-label="Show how this works"><div class="inf-p">${inf}</div>`:''}${b}</section>`;};
const lnk=(act,txt)=>`<button class="lnk" data-act="${act}">${txt} \u203a</button>`;
const ht=cm=>(cm/100).toFixed(2)+' m';
const status=p=>(p.tid===G.user&&G.captain===p.id?'<span class="pill k">C</span> ':'')+(p.rest&&p.tid===G.user?'<span class="pill b">Rest</span> ':'')+status0(p);
const status0=p=>p.ten&&p.tid===G.user?`<span class="pill o">10-day \u00b7 ${Math.max(0,p.ten.until-G.day)}d</span>`:p.tid===G.user&&forBenched(G.user).includes(p)?`<span class="pill r">Not eligible</span>`:p.short&&p.tid===G.user?`<span class="pill o">${p.short.k==='jk'?'Joker':'Short-term'}</span>`:p.loan?`<span class="pill o">${p.loan.gl?(p.loan.from===G.user?'G League':p.tw?'Two-way':'NBA assignee'):'On loan'}</span>`:p.unhappy?`<span class="pill r">Unhappy</span>`:p.inj>0?`<span class="pill r">Injured \u00b7 ${p.inj}</span>`:G.listed.includes(p.id)?`<span class="pill b">Listed</span>`:p.energy<65?`<span class="pill y">Tired</span>`:p.fragile?`<span class="pill y">Fragile</span>`:`<span class="pill g">Fit</span>`;
const IC={
  inbox:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M3 6h18v12H3z"/><path d="M3 7l9 6 9-6"/></svg>',
  med:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/></svg>',
  scout:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l5 5" stroke-linecap="round"/></svg>',
  ball:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M5.6 5.6c3.5 3 3.5 9.8 0 12.8M18.4 5.6c-3.5 3-3.5 9.8 0 12.8M3 12h18"/></svg>',
  save:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M7 19h10.5a4.5 4.5 0 0 0 .6-8.96A6.5 6.5 0 0 0 5.6 9.2 5 5 0 0 0 7 19z"/><path d="M9.3 14l2 2 3.8-3.9"/></svg>',
  arrow:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 4l8 8-8 8"/></svg>',
};
const MI={res:['var(--g)','\u2713'],med:['var(--r)','+'],offer:['var(--or)','\u20ac'],fin:['#7a5af0','\u20ac'],board:['var(--ink3)','B'],staff:['var(--b)','C'],job:['var(--g)','J']};
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.hidden=false;clearTimeout(toast.h);toast.h=setTimeout(()=>{el.hidden=true;},2800);}

/* ===================== Frame ===================== */
function contLabel(){if(typeof ntPend==='function'&&ntPend())return ntPend().camp?'Camp':ntPend().tour?'Tournament':'Int. window';if(pwOpen())return `Portal window \u00b7 day ${G.pw.day+1}`;if(nbaFAOpen())return `Free agency \u00b7 day ${G.nfa.day+1}`;if(UI.view==='match'&&UI.match&&!UI.match.m.done)return 'Live';if(typeof dpOpen==='function'&&dpOpen())return G.dp.wk+1>=G.dp.len?'Withdrawal deadline':`Draft week ${G.dp.wk+1} of ${G.dp.len}`;if(seasonOver())return 'Review';if(UI.view==='prematch'&&userFx())return 'Play live';return userFx()?'Play match':'Continue';}
/* one top bar: identity + rings, date and key numbers, tools, continue */
function clubMorale(){const t=G.teams[G.user],rs=roster(G.user);return clamp((50+t.form.filter(x=>x==='W').length*10-t.form.filter(x=>x==='L').length*6+(rs.length?rs.reduce((s,p)=>s+moodOf(p),0)/rs.length:60))/2,10,100);}
function topbRing(l,v,full){v=Math.round(clamp(v||0,0,100));const C=2*Math.PI*15,col=v<35?'var(--r)':v>=70?'#5fe08f':'var(--or)';
  return `<div class="topb-r" title="${full||l}: ${v}%" role="img" aria-label="${full||l} ${v} percent"><svg viewBox="0 0 36 36" aria-hidden="true"><circle cx="18" cy="18" r="15" class="bg"/><circle cx="18" cy="18" r="15" class="fg" style="stroke:${col};stroke-dasharray:${(C*v/100).toFixed(1)} ${C.toFixed(1)}"/></svg><b>${v}</b><small>${l}</small></div>`;}
function topbId(){const nt=typeof ntMode==='function'&&ntMode();let mark,name,sub,R;
  if(nt){const J=G.nt.job,c=J.c;mark=`<span class="topb-fl">${ntFlag(c,40)}</span>`;name=esc(ntName(c));sub=`${esc(G.mgr)} · National team head coach`;R=[['Trust',J.trust==null?60:J.trust,'Federation trust'],['Fans',J.fans==null?60:J.fans,'Fans'],['Chem',ntChem(),'Chemistry']];}
  else{const t=G.teams[G.user];mark=crest(t,'dk');name=esc(clubDisplayName(t));sub=`${esc(G.mgr)} · Head Coach`;R=[[isCol(t)?'AD':'Board',G.board,isCol(t)?'Athletic director confidence':'Board confidence'],['Fans',G.fans,'Fans'],['Morale',clubMorale(),'Team morale']];}
  return `<div class="topb-id">${mark}<div class="topb-nm"><b title="${name}">${name}</b><small>${sub}</small></div><div class="topb-rg">${R.map(r=>topbRing(...r)).join('')}</div></div>`;}
function topbTools(){const nt=typeof ntMode==='function'&&ntMode(),J=G&&G.nt&&G.nt.job;let sw='';
  if(nt)sw=`<button class="topb-b topb-sw" data-act="ntmode" title="Back to club">${crest(G.teams[G.user])}<span>Club</span></button>`;
  else if(J)sw=`<button class="topb-b topb-sw" data-act="ntmode" title="National team">${ntFlag(J.c,30)}<span>Nat. team</span></button>`;
  return `<div class="topb-tl">${sw}<button class="topb-b" data-act="settings" title="Settings" aria-label="Settings">${iIc('gear')}</button><button class="topb-b" data-act="savegame" title="Saved automatically" aria-label="Saved automatically, open your careers">${IC.save}</button></div>`;}
/* ---------- settings (kept in this browser, apart from the saved career) ---------- */
var BMSET=(()=>{const d={txt:1,speed:1,snd:0,cur:''};try{const s=JSON.parse(localStorage.getItem('bm-settings-v1')||'{}');for(const k in d)if(s[k]!=null)d[k]=s[k];}catch(e){}return d;})();
function setSave(){try{localStorage.setItem('bm-settings-v1',JSON.stringify(BMSET));}catch(e){}}
// Text size zooms the page. Media queries still see the real window, so the layout breakpoints are repeated as classes for the width that is left.
function setApply(){let z=[1,1.1,1.2].includes(+BMSET.txt)?+BMSET.txt:1;if(window.innerWidth<700)z=Math.min(z,1.1);const R=document.documentElement,w=window.innerWidth/z;R.style.setProperty('--z',z);document.body.style.zoom=z===1?'':z;
  R.classList.toggle('ew1320',z>1&&w<=1320);R.classList.toggle('ew1240',z>1&&w<=1240);R.classList.toggle('ew1000',z>1&&w<=1000);}
window.addEventListener('resize',()=>{try{setApply();}catch(e){}});
function settingsModal(){const S=BMSET,row=(l,d,c)=>`<div class="set-r"><div><b>${l}</b><small>${d}</small></div><div class="seg">${c}</div></div>`,bt=(k,v,l)=>`<button class="${String(S[k])===String(v)?'on':''}" data-act="setv:${k}:${v}">${l}</button>`;
  const has=!!(G&&!G.demo);
  return `<div class="ovl" data-act="ovl"><div class="modal set" role="dialog" aria-modal="true" aria-label="Settings" style="max-width:560px"><div class="ch"><h3>Settings</h3><button class="lnk" data-act="close">Close \u2715</button></div>
  ${row('Text size','Makes everything on screen larger.',bt('txt',1,'Normal')+bt('txt',1.1,'Large')+bt('txt',1.2,'Larger'))}
  ${row('Live match speed','The speed a live match starts at.',bt('speed',1,'1\u00d7')+bt('speed',2,'2\u00d7')+bt('speed',4,'4\u00d7'))}
  ${row('Sound','Clicks, the buzzer and the crowd on big plays.',bt('snd',0,'Off')+bt('snd',1,'On'))}
  ${row('Currency symbol','Only the symbol changes, amounts stay the same.',bt('cur','','Auto')+bt('cur','\u20ac','\u20ac')+bt('cur','$','$'))}
  <div class="set-r"><div><b>Saved careers</b><small>Switch between careers, export a career as a file or import one.</small></div><div class="btns"><button class="btn sm" data-act="saves">Open…</button></div></div>
  ${has?`<div class="set-r set-d"><div><b>This career</b><small>${UI.setDel?'This removes the career you are playing from this browser for good.':'Delete the career you are playing and return to the start screen.'}</small></div><div class="btns">${UI.setDel?`<button class="btn sm" data-act="setdel:0">Keep it</button><button class="btn sm set-x" data-act="setdel:2">Delete for good</button>`:`<button class="btn sm" data-act="setdel:1">Delete save\u2026</button>`}</div></div>`:''}
  <p class="set-n">Settings are stored in this browser only.</p></div></div>`;}
/* ---------- sound: small synthesised effects, off unless switched on ---------- */
const SFX={ctx:null,
  ac(){if(!BMSET.snd)return null;try{if(!this.ctx){const A=window.AudioContext||window.webkitAudioContext;if(!A)return null;this.ctx=new A();}if(this.ctx.state==='suspended')this.ctx.resume();return this.ctx;}catch(e){return null;}},
  tone(f0,f1,dur,vol,type){const c=this.ac();if(!c)return;const o=c.createOscillator(),g=c.createGain(),t=c.currentTime;o.type=type||'sine';o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(30,f1),t+dur);g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g).connect(c.destination);o.start(t);o.stop(t+dur+.02);},
  click(){this.tone(1500,900,.045,.035,'triangle');},
  buzzer(){const c=this.ac();if(!c)return;[196,208].forEach(f=>{const o=c.createOscillator(),g=c.createGain(),t=c.currentTime;o.type='sawtooth';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(.06,t+.02);g.gain.setValueAtTime(.06,t+.75);g.gain.linearRampToValueAtTime(.0001,t+.9);o.connect(g).connect(c.destination);o.start(t);o.stop(t+.95);});},
  crowd(big){const c=this.ac();if(!c)return;const dur=big?2.6:1.5,n=Math.floor(c.sampleRate*dur),b=c.createBuffer(1,n,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;
    const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain(),t=c.currentTime;s.buffer=b;f.type='bandpass';f.frequency.setValueAtTime(700,t);f.frequency.linearRampToValueAtTime(big?1500:1100,t+.35);f.Q.value=.7;
    g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(big?.16:.09,t+.3);g.gain.exponentialRampToValueAtTime(.0001,t+dur);s.connect(f).connect(g).connect(c.destination);s.start(t);}};
document.addEventListener('click',e=>{if(BMSET.snd&&e.target.closest('[data-act],button'))SFX.click();},true);
// sounds for what just happened in the live match (skipped when many events arrive at once, as in Sim to end)
function matchSfx(M){const m=M.m,n=m.ev.length;if(M.sfxN==null){M.sfxN=n;return;}const from=M.sfxN;M.sfxN=n;if(!BMSET.snd||n<=from)return;
  const T=evMeta(m).T,ui=m.s[0].tid===(m.ntU!=null?m.ntU:G.user)?0:1;let buzz=false,cheer=0;
  for(let i=from;i<n;i++){const ev=m.ev[i];if(ev.type==='period'&&/^(End of|Final|Half)/.test(ev.txt))buzz=true;else if(T[i]&&T[i].big&&n-from<=3)cheer=Math.max(cheer,ev.side===ui?(T[i].t.length?2:1):0);}
  if(buzz)SFX.buzzer();else if(cheer)SFX.crowd(cheer>1);}

/* ---------- 1. moment screens ---------- */
function momentPush(x){(UI.mq=UI.mq||[]).push(x);}
function momentScan(){if(!G||!G.teams||G.user==null||(typeof ntMode==='function'&&ntMode()))return;const T=G.teams[G.user];if(!T)return;
  // a new player who is at once one of our three best
  const key=G.user+'|'+G.season+'|'+(G.mgr||''),R=roster(G.user);
  if(UI.rsKey!==key){UI.rsKey=key;UI.rsSeen=new Set(R.map(p=>p.id));}
  else{const top=R.slice().sort((a,b)=>b.o-a.o).slice(0,3);for(const p of R)if(!UI.rsSeen.has(p.id)){UI.rsSeen.add(p.id);if(top.includes(p)&&p.yth==null)momentPush({k:'sign',pid:p.id});}
    for(const id of [...UI.rsSeen])if(!R.some(p=>p.id===id))UI.rsSeen.delete(id);}
  // end of season: titles, promotion, relegation
  if(UI.view==='season'&&seasonOver()&&UI.sfSeen!==key){UI.sfSeen=key;try{const F=seasonFacts(),won=[];
      if(F.champ&&F.champ.id===G.user)won.push(F.title);
      if(F.h&&F.h.dom&&F.h.dom.champName===T.name)won.push((F.h.dom.name||'ABA League')+' champions');
      try{const P=typeof pok==='function'?pok():null;if(P&&P.user==='Winner')won.push(NCUP[P.c].name+' winners');}catch(e){}
      won.forEach(w=>momentPush({k:'cup',t:w}));
      if(/promot/i.test(F.fin)&&!/relegat/i.test(F.fin))momentPush({k:'up',t:F.fin});else if(/relegat/i.test(F.fin))momentPush({k:'down',t:F.fin});
    }catch(e){console.error(e);}}
  if((G.sacked||G.bankrupt)&&UI.skSeen!==key){UI.skSeen=key;momentPush({k:'sack'});}}
const TROPHY='<svg viewBox="0 0 120 120" aria-hidden="true"><defs><linearGradient id="tg1" x1="0" x2="1"><stop offset="0" stop-color="#b8860b"/><stop offset=".45" stop-color="#ffe9a3"/><stop offset="1" stop-color="#c9971a"/></linearGradient></defs><path d="M34 14h52v26c0 17-11 30-26 30S34 57 34 40z" fill="url(#tg1)"/><path d="M34 22H16c0 20 8 30 22 31M86 22h18c0 20-8 30-22 31" fill="none" stroke="url(#tg1)" stroke-width="7" stroke-linecap="round"/><path d="M53 68h14v18H53z" fill="#c9971a"/><path d="M36 86h48l6 18H30z" fill="url(#tg1)"/><path d="M46 22c0 16 3 28 10 36" stroke="#fff" stroke-opacity=".55" stroke-width="4" fill="none" stroke-linecap="round"/></svg>';
function momentHTML(){const x=(UI.mq||[])[0];if(!x||!G)return '';const T=G.teams[G.user],c1=lum(T.c1)>.85?T.c2:T.c1,more=UI.mq.length>1;let kick,title,sub,art,extra='',cls='mxk-'+x.k;
  if(x.k==='sign'){const p=G.players[x.pid];if(!p){UI.mq.shift();return momentHTML();}kick='New signing';title=esc(pname(p));sub=`${p.pos} \u00b7 ${p.age} years \u00b7 ${esc(p.nat)}`;
    art=`<span class="avatar ph mx-av">${avatarIn(p,p.no)}</span>`;extra=`<div class="mx-st"><div><b>${ovrTxt(p)}</b><small>Overall</small></div><div><b>${eur(p.sal)}</b><small>Per season</small></div><div><b>${p.yrs}</b><small>Year${p.yrs===1?'':'s'}</small></div></div>`;}
  else if(x.k==='cup'){kick=esc(seasonStr());title=esc(x.t);sub=esc(T.name);art=`<span class="mx-tr">${TROPHY}</span>`;extra=`<div class="mx-cf" aria-hidden="true">${Array.from({length:36},(_,i)=>`<i style="left:${(i*2.78+((i*37)%9)).toFixed(1)}%;animation-delay:${((i*53)%30)/10}s;animation-duration:${3+((i*17)%20)/10}s;background:${['#ffd75e','#fff',c1,'#ff6b00'][i%4]}"></i>`).join('')}</div>`;}
  else if(x.k==='up'){kick='Promotion';title='Going up';sub=`${esc(T.name)} \u00b7 ${esc(x.t)}`;art=`<span class="mx-cr">${crest(T)}</span>`;}
  else if(x.k==='down'){kick='Relegation';title='Relegated';sub=`${esc(T.name)} \u00b7 ${esc(x.t)}`;art=`<span class="mx-cr">${crest(T)}</span>`;}
  else{kick=G.bankrupt?'Bankruptcy':'Board decision';title=G.bankrupt?'The club is bankrupt':G.expired?'Contract ended':G.resigned?'You resigned':'Dismissed';sub=`${esc(G.mgr)} \u00b7 ${esc(T.name)}`;art=`<span class="mx-cr">${crest(T)}</span>`;}
  return `<div class="mx ${cls}" style="--mc:${c1}" role="dialog" aria-modal="true" aria-label="${kick}: ${title}">${extra&&x.k==='cup'?extra:''}<div class="mx-in">${art}${x.k!=='cup'&&x.k!=='sign'?'':`<span class="mx-cr s">${crest(T)}</span>`}<small class="mx-k">${kick}</small><h2>${title}</h2><p>${sub}</p>${x.k==='sign'?extra:''}<button class="mx-b" data-act="momnext">${more?'Next':'Continue'}</button></div></div>`;}
function momentPaint(){let el=document.getElementById('moment');if(!el){el=document.createElement('div');el.id='moment';document.body.appendChild(el);}
  const x=(UI.mq||[])[0],key=x?JSON.stringify(x)+UI.mq.length:'';if(el.dataset.k===key)return;el.dataset.k=key;el.innerHTML=momentHTML();
  if(x){if(x.k==='cup'||x.k==='up')SFX.crowd(true);else if(x.k==='sign')SFX.crowd(false);const b=el.querySelector('.mx-b');if(b)try{b.focus({preventScroll:true});}catch(e){}}}
function headerHTML(){const t=G.teams[G.user],room=G.fin.wageBudget-wageBill(G.user),live=UI.view==='match'&&UI.match&&!UI.match.m.done;
  return `<header class="topb">${topbId()}
  <div class="hmid"><div class="date"><b>${dateStr()}</b><span>${stepLabel()} \u00b7 ${seasonStr()}</span></div>
  <div class="hstat"><small>${userIsCup()&&cupUser()?`${cupUser().short} \u00b7 Group ${cupUser().grp}`:userIsNL()&&nlUser()?`${NLCFG[nlUser().code].short}${nlUser().groups?` \u00b7 ${t.grp}`:''}`:userIsKls()?(G.kls&&G.kls.po?'KLS \u00b7 Super League':'KLS \u00b7 First League'):userIsBih()?(G.bih&&G.bih.po&&(G.bih.seeds||[]).includes(G.user)?'BiH \u00b7 Play-off':'BiH \u00b7 Liga 14'):userIs2()?`ABA 2 \u00b7 Group ${dom2GroupOf(G.user)}`:userIsDom()?`ABA \u00b7 ${(domTableOf(G.user)||{name:'League'}).name}`:'Euroleague'}</small><b>${ordn(userIsDom()&&G.dom.top8&&!G.dom.top8.includes(G.user)?userRank()-8:userRank())} \u00b7 ${userIsCup()&&cupUser()?cupUser().rec.slice(0,2).join('\u2013'):userIsNL()&&nlUser()?nlRec(nlUser(),G.user).slice(0,2).join('\u2013'):userIsKls()?`${t.kw||0}\u2013${t.kl||0}`:userIsBih()?`${t.bw||0}\u2013${t.bl||0}`:userNotEL()?`${t.dw}\u2013${t.dl}`:`${t.w}\u2013${t.l}`}</b></div>
  ${isCol(G.teams[G.user])?`<div class="hstat" title="Revenue sharing from the athletic department plus the booster collective. College basketball has no transfer fees."><small>NIL pool</small><b class="pos">${eur(G.fin.wageBudget)}</b></div>`:`<div class="hstat"><small>${userNBA()?'Club cash':'Transfer budget'}</small><b class="${G.fin.bal>=0?'pos':'neg'}">${eur(G.fin.bal)}</b></div>`}
  <div class="hstat"><small>${isCol(G.teams[G.user])?'NIL room':'Wage room'}</small><b class="${room>=0?'':'neg'}">${eur(room)}</b></div></div>
  ${topbTools()}<button class="cont" data-act="continue" ${live?'disabled':''}>${contLabel()}${IC.arrow}</button></header>`;}
function clubHTML(){const t=G.teams[G.user],unread=G.inbox.filter(m=>!m.read).length,inj=roster(G.user).filter(p=>p.inj>0).length;
  const rs=roster(G.user),morale=clamp((50+t.form.filter(x=>x==='W').length*10-t.form.filter(x=>x==='L').length*6+(rs.length?rs.reduce((s,p)=>s+moodOf(p),0)/rs.length:60))/2,10,100);
  return `<div class="club gut">${crest(t,'dk')}<div><h2>${esc(clubDisplayName(t))}</h2><div class="who"><span>${esc(G.mgr)} \u00b7 Head Coach</span></div></div>
  <div class="meters">${[[isCol(G.teams[G.user])?'AD':'Board',G.board],['Fans',G.fans],['Morale',morale]].map(([l,v])=>`<div class="meter"><small>${l} <b>${Math.round(v)}%</b></small><div class="bar"><i style="width:${v}%"></i></div></div>`).join('')}</div>
  <div class="icons"><button class="ic" data-act="savegame" title="Saved automatically">${IC.save}<span>Saved</span></button></div></div>`;}
const TABS=[['home','Home'],['squad','Squad'],['tactics','Tactics'],['training','Training'],['staff','Staff'],['transfers','Transfers'],['finances','Finances'],['club','Club'],['business','Business'],['comp','Competitions'],['inbox','Inbox']];
const NI={
  home:'<path d="M4 11l8-7 8 7v9h-5v-6H9v6H4z"/>',
  inbox:'<path d="M3 6h18v12H3z"/><path d="M3 7l9 6 9-6"/>',
  feed:'<path d="M4 5h16v11H9l-5 4z"/><path d="M8 9h8M8 12.500h5"/>',
  squad:'<circle cx="9" cy="8" r="3.2"/><path d="M3 20c0-3.6 2.7-6 6-6s6 2.4 6 6"/><path d="M16 5.2a3 3 0 010 5.6M18 14.4c1.9.8 3 2.9 3 5.6"/>',
  tactics:'<path d="M4 4h16v16H4z"/><path d="M8 8l3 3M11 8l-3 3"/><circle cx="15.5" cy="15.5" r="2.2"/><path d="M10 15c1.5 0 2.5-1 3-2.5" stroke-dasharray="1.6 1.8"/>',
  training:'<path d="M3 10v4M6 7v10M18 7v10M21 10v4M6 12h12"/>',
  medical:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/>',
  staff:'<circle cx="12" cy="7.5" r="3.5"/><path d="M5 21c0-4 3-7 7-7s7 3 7 7"/><path d="M12 14l-1.5 3 1.5 4 1.5-4z"/>',
  finances:'<path d="M17.5 6.5A7 7 0 1017.5 17.5"/><path d="M4 10h9M4 14h9"/>',
  club:'<path d="M12 3l8 3v6c0 4.5-3.4 8-8 9-4.6-1-8-4.5-8-9V6z"/>',
  business:'<path d="M3 8h18v12H3z"/><path d="M9 8V5h6v3M3 13h18"/>',
  transfers:'<path d="M4 8h14l-3.5-3.5M20 16H6l3.5 3.5"/>',
  scout:'<circle cx="11" cy="11" r="6.5"/><path d="M16 16l5 5"/>',
  comp:'<path d="M7 4h10v5a5 5 0 01-10 0z"/><path d="M7 6H4c0 3 1.5 4.5 3.5 4.5M17 6h3c0 3-1.5 4.5-3.5 4.5M12 14v3M8 21h8M9.5 17h5v4h-5z"/>',
  league:'<path d="M5 5h14M5 10h14M5 15h14M5 20h9"/>',
  match:'<circle cx="12" cy="12" r="9"/><path d="M5.6 5.6c3.5 3 3.5 9.8 0 12.8M18.4 5.6c-3.5 3-3.5 9.8 0 12.8M3 12h18"/>',
  more:'<circle cx="5" cy="12" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="19" cy="12" r="1.6"/>',
  save:'<path d="M7 19h10.5a4.5 4.5 0 0 0 .6-8.96A6.5 6.5 0 0 0 5.6 9.2 5 5 0 0 0 7 19z"/><path d="M9.3 14l2 2 3.8-3.9"/>',
};
const nIc=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${NI[k]||NI.more}</svg>`;
function myLeagueKey(){try{const L=compList().filter(x=>x.me&&x.k!=='nt'&&x.k!=='pok');const d=L.find(x=>x.g>0)||L[0];return d?d.k:null;}catch(e){return null;}}
// one source for sidebar, bottom bar and More sheet: [key, label, act, isOn, badge]
function navGroups(){const nt=typeof ntMode==='function'&&ntMode(),on=k=>UI.view==='main'&&UI.tab===k;
  if(nt){const un=G.inbox.filter(m=>!m.read&&m.type==='nt').length;return [[null,NT_TABS.map(([k,l])=>[k==='training'?'training':k,k==='squad'?(ntPend()?'Squad':'Call-ups'):l,'tab:'+k,on(k),k==='inbox'?un:0])]];}
  const un=G.inbox.filter(m=>!m.read).length,inj=roster(G.user).filter(p=>p.inj>0).length,lk=myLeagueKey(),scOn=on('transfers')&&UI.tr===(userNBA()?'market':'watch'),lgOn=on('comp')&&lk&&(UI.comp||'table')===lk;
  return [[null,[['home','Home','tab:home',on('home'),0],['inbox','Inbox','tab:inbox',on('inbox'),un]]],
    ['Team',[['squad','Squad','tab:squad',on('squad'),0],['tactics','Tactics','tab:tactics',on('tactics'),0],['training','Training','tab:training',on('training'),0],['medical','Medical','tab:medical',on('medical'),inj]]],
    ['Club',[['staff','Staff','tab:staff',on('staff'),0],['finances','Finances','tab:finances',on('finances'),0],['business','Business','tab:business',on('business'),0],['club','Club','tab:club',on('club'),0]]],
    ['Market',[['transfers','Transfers','tab:transfers',on('transfers')&&!scOn,0],['scout','Scouting','navgo:scout',scOn,0]]],
    ['World',[['comp','Competitions','navgo:comp',on('comp')&&!lgOn,0],['league','League','navgo:league',lgOn,0],['feed','Social','tab:feed',on('feed'),feedUnread()]]]];}
const navBtn=([k,l,a,o,n],cls)=>`<button class="${cls}${o?' on':''}" data-act="${a}" title="${l}"${o?' aria-current="page"':''}>${nIc(k)}<span>${l}</span>${n?`<em${k==='medical'?' class="o"':''}>${n}</em>`:''}</button>`;
function navHTML(){return `<aside class="snav" aria-label="Main">${navGroups().map(([g,L])=>`<div class="snav-g">${g?`<h6>${g}</h6>`:''}${L.map(x=>navBtn(x,'snav-b')).join('')}</div>`).join('')}</aside>`;}
function bnavHTML(){const all=navGroups().flatMap(g=>g[1]),f=k=>all.find(x=>x[0]===k),live=UI.view==='match'&&UI.match&&!UI.match.m.done,
    pick=['home','squad',null,typeof ntMode==='function'&&ntMode()?'comp':'transfers'].map(k=>k&&f(k)),shown=pick.filter(Boolean).map(x=>x[0]),
    moreOn=!UI.more&&all.some(x=>x[3]&&!shown.includes(x[0])),moreN=all.filter(x=>!shown.includes(x[0])).reduce((s,x)=>s+(x[0]==='inbox'?x[4]:0),0);
  return `<nav class="bnav" aria-label="Main">${navBtn(pick[0],'bn')}${navBtn(pick[1],'bn')}<button class="bn bn-m${UI.view==='prematch'||UI.view==='match'?' on':''}" data-act="continue" ${live?'disabled':''}>${nIc('match')}<span>${esc(contLabel())}</span></button>${navBtn(pick[3],'bn')}<button class="bn${moreOn||UI.more?' on':''}" data-act="navmore" aria-expanded="${!!UI.more}">${nIc('more')}<span>More</span>${moreN?`<em>${moreN}</em>`:''}</button></nav>
  ${UI.more?`<div class="more-bg" data-act="navmore"></div><div class="more" role="dialog" aria-label="All sections">${navGroups().map(([g,L])=>`<div class="more-g">${g?`<h6>${g}</h6>`:''}<div class="more-l">${L.map(x=>navBtn(x,'more-b')).join('')}</div></div>`).join('')}<div class="more-g"><div class="more-l"><button class="more-b" data-act="savegame">${nIc('save')}<span>My careers</span></button><button class="more-b" data-act="settings">${iIc('gear')}<span>Settings</span></button></div></div></div>`:''}`;}
// Phones: drop the least important columns of a table until it fits; if it still does not fit, keep the first column in view while scrolling.
const TBL_HIDE=['PA','PF','NAT','LAST 5','FORM','STL','BLK','TO','NO','3P','FT','AGE','POS','POT','MIN'];
function tblFit(){if(window.innerWidth>700)return;document.querySelectorAll('#app table').forEach(t=>{const w=t.closest('.tw');if(!w||w.classList.contains('trx')||!t.tHead||!t.tHead.rows[0])return;
  const over=()=>t.scrollWidth>w.clientWidth+1;if(!over())return;const H=[...t.tHead.rows[0].cells].map(c=>c.textContent.trim().toUpperCase());
  for(const k of TBL_HIDE){const i=H.indexOf(k);if(i<0||(i===0&&k!=='NO'))continue;for(const r of t.rows)if(r.cells.length===H.length)r.cells[i].classList.add('hx');if(!over())return;}
  w.classList.add('twx');});}
window.addEventListener('resize',()=>{clearTimeout(tblFit.h);tblFit.h=setTimeout(()=>{document.querySelectorAll('.hx').forEach(c=>c.classList.remove('hx'));document.querySelectorAll('.twx').forEach(c=>c.classList.remove('twx'));try{tblFit();}catch(e){}},150);});
function homeTrim(){if(window.innerWidth>700)return;document.querySelectorAll('#app .g-home table').forEach(t=>{const B=t.tBodies[0];if(!B)return;const rows=[...B.rows].filter(r=>r.cells.length>2);if(rows.length<=7)return;let u=rows.findIndex(r=>r.classList.contains('me'));if(u<0)u=0;const a=Math.max(0,Math.min(u-2,rows.length-5));rows.forEach((r,i)=>{if(i<a||i>=a+5)r.classList.add('hr-trim');});});}
function render(){try{const r=render0();try{matchFocus();tblFit();homeTrim();}catch(e){}try{momentScan();momentPaint();}catch(e){console.error(e);}return r;}catch(err){uiErr('render',err);}}
function render0(){
  if(G&&typeof tidFix==='function'&&!(render0.fx||(render0.fx=new WeakSet())).has(G)){render0.fx.add(G);try{tidFix();}catch(err){console.error(err);}}
  const app=document.getElementById('app');
  if(!G||UI.view==='start'){app.innerHTML=startHTML()+`<button class="set-fab" data-act="settings" title="Settings" aria-label="Settings">${iIc('gear')}</button>`+(UI.modal&&UI.modal.kind==='settings'?settingsModal():'');csScroll();try{csCardFix();csStripFix();}catch(e){}if(window.csBgMount)csBgMount();return;}
  if(G.sacked||G.bankrupt){app.innerHTML=careerHTML()+modalHTML();return;}
  let body;
  if(UI.view==='prematch'&&userFx())body=prematchHTML();
  else if(UI.view==='match'&&UI.match)body=matchHTML();
  else if(UI.view==='season'&&seasonOver())body=seasonHTML();
  else if(ntMode()){UI.view='main';if(!NT_TABS.some(x=>x[0]===UI.tab))UI.tab='home';if(UI.tab==='comp')UI.comp='nt';body=({home:ntModeHome,squad:()=>ntPend()?(ntPend().camp?ntCampPanel():ntRotHTML()):ntMyHTML(),tactics:ntTacHTML,training:ntCampHTML,staff:ntStaffHTML,comp:compHTML,inbox:inboxHTML})[UI.tab]();}
  else{UI.view='main';if(UI.tab!=='feed')UI.fdSeen0=null;body=({feed:socialFeedHTML,home:homeHTML,squad:squadHTML,medical:medicalHTML,tactics:tacticsHTML,training:trainingHTML,staff:staffHTML,transfers:transfersHTML,finances:financesHTML,club:clubTabHTML,business:businessHTML,comp:compHTML,inbox:inboxHTML})[UI.tab]();}
  app.innerHTML=headerHTML()+`<div class="shell">`+navHTML()+`<main class="main gut"><div class="inner">${G&&G.demo?'<div style="background:#fff4cc;border:1px solid #e0c060;color:#5a4500;padding:10px 14px;border-radius:8px;margin-bottom:12px;font-size:14px"><b>Demo career</b> \u00b7 nothing is saved. The demo jumps straight to the event, so the club side still shows a day in November; in a real career tournaments are played in the summer, before the club pre-season. Open the game without the <code>#nt-…</code> ending to return to your own career.</div>':''}${body}</div></main></div>`+bnavHTML()+modalHTML();try{ntTheme();}catch(e){}
  if(UI.view==='match')updMatch();
  if(UI.view==='main'&&UI.tab==='club'&&window.arena3dMount)arena3dMount();
}

/* ===================== Home ===================== */
// free agent market trend: days unsigned and where his demand is heading
function faTag(p){const f=faTrend(p);if(f===1&&!p.faHot)return '';const pc=Math.round((f-1)*100);
  return ` <small class="${pc<0?'pos':'neg'}" style="white-space:nowrap" title="${faDays(p)} days unsigned${p.faHot&&p.faHot>faAbs()?' \u00b7 other clubs interested':''}">${pc<0?'\u2193':'\u2191'}${Math.abs(pc)}%</small>`;}
function faBidBar(){const L=Object.keys(G.faBid||{}).map(i=>[G.players[i],G.faBid[i]]).filter(x=>x[0]);if(!L.length)return '';return `<section class="fb"><header><b>Waiting for an answer</b><small>Not signed yet. Other clubs want them too, and they decide on the next game days.</small></header>${L.map(([p,B])=>`<div class="fb-r"><button class="ct-n" data-act="prof:${p.id}"><b>${esc(pname(p))}</b><small>Your offer ${eur(B.wage)} · also ${B.rivals.map(r=>`${esc(G.teams[r.tid].name)} ${eur(r.wage)}`).join(', ')}</small></button><em>${B.left} game day${B.left>1?'s':''}</em><button class="fb-u" data-act="fabid:${p.id}" ${B.imp>=2?'disabled':''}>Raise +10%</button></div>`).join('')}</section>`;}
function faBidBox(p){const B=(G.faBid||{})[p.id];if(!B)return '';return `<p style="font-size:13.5px;margin-bottom:8px"><span class="pill o">Deciding</span> Your offer ${eur(B.wage)} \u00b7 also: ${B.rivals.map(r=>`${esc(G.teams[r.tid].name)} ${eur(r.wage)}`).join(', ')} \u00b7 decision in ${B.left} game day${B.left>1?'s':''}</p><div class="btns" style="margin-bottom:8px"><button class="btn sm p" data-act="fabid:${p.id}" ${B.imp>=2?'disabled':''}>Raise offer +10%</button></div>`;}
function forWarn(p){if(userNBA())return '';const me=G.teams[G.user],R=ruleOfTeam(me);if(!R||R.floor||!isForeign(p,R)||p.homeOK===me.short)return '';const n=forCount(G.user,R);return n<R.cap?'':`<div class="sec" style="padding-block:8px"><p class="neg" style="font-size:13px">${esc(R.txt)}. You already have ${n} foreign players, so he could not play until you let one go.</p></div>`;}
function forLine(){if(userNBA())return '';const R=ruleOfTeam(G.teams[G.user]);if(!R)return '';const n=forCount(G.user,R),b=forBenched(G.user);return `<div style="margin-bottom:14px">${card('League rule',`<div class="sec" style="padding-block:10px"><p style="font-size:14px">${esc(R.txt)}. ${R.floor?`Your starting five is set so this is met.`:`Foreign players in your squad: <b>${n}</b> of ${R.cap}.`}${b.length?` <span class="neg">Not eligible: ${b.map(p=>esc(pname(p))).join(', ')}.</span>`:''}</p></div>`)}</div>`;}
function faInfo(p){if(p.tid!=null||p.nfa||p.yth!=null||userNBA())return '';const d=faDays(p),f=faTrend(p),pc=Math.round((f-1)*100),hot=p.faHot&&p.faHot>faAbs();
  return `${faBidBox(p)}<p class="mut" style="font-size:13px;margin-bottom:8px">Unsigned for ${d} day${d===1?'':'s'}${hot?' \u00b7 <b class="neg">other clubs are interested</b>':''}${preOn()?' \u00b7 pre-season market':''} \u00b7 wage demand ${pc===0?'unchanged':`${pc<0?'down':'up'} ${Math.abs(pc)}%`} (${eur(demand(p))} per season)</p>`;}
function seasonTicketCard(){const S=G.fin.stk&&G.fin.stk.season===G.season?G.fin.stk:null;let b;
  if(S)b=`<div class="cb">${kv('Sold',`${S.sold.toLocaleString('en-GB')} seats · ${Math.round(S.disc*100)}% off`)}${kv('Income received',eur(S.income))}${kv('Home games covered',S.n)}<p class="mut" style="margin-top:10px;font-size:13.5px">These seats are always filled, but only the remaining seats earn gate on match days.</p></div>`;
  else if(!preOn())b=`<div class="cb"><p class="mut" style="font-size:13.5px">Season tickets go on sale in the pre-season, before the next season starts.</p></div>`;
  else b=`<div class="cb"><p class="mut" style="font-size:13.5px;margin-bottom:10px">The money comes in now, but these seats earn nothing on match days. A bigger discount sells more.</p>${[.1,.2,.3,.4].map(d=>{const F=stForecast(d);return `<div class="msg" style="cursor:default"><span style="flex:1;min-width:0"><b>${Math.round(d*100)}% off</b><small style="display:block">${F.sold.toLocaleString('en-GB')} seats · ${eur(F.income)} now · ${F.n} home games</small></span><button class="btn sm p" data-act="stsell:${d}">Sell</button></div>`;}).join('')}</div>`;
  return card('Season tickets',b);}
function namingCard(){if(!nameOn())return '';const t=G.teams[G.user],N=t.naming;
  const b=N?`<div class="cb">${kv('Arena',esc(t.arena))}${kv('Sponsor',esc(N.co))}${kv('Fee',`${eur(N.fee)} per season`)}${kv('Seasons left',N.left)}<p class="mut" style="margin-top:10px;font-size:13.5px">When the deal ends, the arena is the ${esc(N.orig)} again.</p></div>`:`<div class="sec" style="padding-block:10px"><p class="mut" style="font-size:13.5px">Now: ${esc(t.arena)}. Sell the name of the arena for a yearly fee.</p></div>${nameOffers().map((o,i)=>`<div class="msg" style="cursor:default"><span style="flex:1;min-width:0"><b>${esc(o.co)} Arena</b><small style="display:block">${eur(o.fee)} per season · ${o.yrs} seasons</small></span><button class="btn sm p" data-act="namesign:${i}">Accept</button></div>`).join('')}`;
  return card('Arena naming rights',b);}
function teamExtra(p){if(p.tid!==G.user)return '';const m=moodOf(p),cap=G.captain===p.id,pair=(G.mentor||{})[p.id],men=Object.entries(G.mentor||{}).find(([a,b])=>+b===p.id);
  return `<p style="font-size:13.5px;margin-bottom:8px"><b>${moodLabel(m)}</b> (${Math.round(m)}%) · ${PERSN[persOf(p)]}${cap?' · <span class="pill k">Captain</span>':''}${p.ptPromise?` · <span class="pill o">Minutes promised</span>`:''} · <span class="pill k">${ROLES[pRole(p)].n}</span>${pair?` · Mentor: ${esc(pname(G.players[pair]||{f:'',l:''}))}`:''}${men?` · Mentoring ${esc(pname(G.players[men[0]]||{f:'',l:''}))}`:''}</p>
  ${isCol(G.teams[G.user])?rsLine(p):''}<div class="btns" style="margin-bottom:8px"><button class="btn sm" data-act="roles">Change role</button><button class="btn sm" data-act="talk:${p.id}">Talk to him</button>${cap?'':`<button class="btn sm" data-act="captain:${p.id}">Make captain</button>`}<button class="btn sm ${p.rest?'p':''}" data-act="rest:${p.id}">${p.rest?'Resting next game ✓':'Rest next game'}</button>${talentOK(p)?`<button class="btn sm" data-act="mentor:${p.id}">${pair?'Change mentor':'Assign mentor'}</button>`:''}</div>`;}
function profExtra(p){if(p.prospect||userNBA())return '';const mine=p.tid===G.user,c=clauseOf(p),own=p.sellOn&&p.sellOn.to===G.user&&!mine,w=G.watch&&G.watch[p.id];let h='';
  if(c)h+=`<p style="font-size:13.5px;margin-bottom:8px"><span class="pill b">Release clause</span> ${eur(c)}${mine?' \u00b7 other clubs can trigger it':''}</p>`;
  if(own)h+=`<p style="font-size:13.5px;margin-bottom:8px"><span class="pill g">Sell-on</span> We get ${p.sellOn.pct}% of his next transfer</p>`;
  const btns=(c&&!mine&&G.phase==='reg'&&!justJoined(p)?`<button class="btn sm p" data-act="clause:${p.id}">Pay release clause</button>`:'')+(!mine&&p.yth==null?`<button class="btn sm" data-act="watch:${p.id}">${w?'\u2605 On watchlist':'\u2606 Add to watchlist'}</button>`:'');
  return h+(btns?`<div class="btns" style="margin-bottom:8px">${btns}</div>`:'');}
function ddCard(){if(!ddOn()||!G.dd||G.dd.season!==G.season)return '';const L=G.dd.deals.filter(d=>{const p=G.players[d.pid];return p&&p.tid===d.tid&&!p.loan;});
  return `<div style="margin-bottom:14px">${card(`Deadline Day \u00b7 ${ddLeft()} round${ddLeft()>1?'s':''} left`,`<div class="sec" style="padding-block:10px"><p class="mut" style="font-size:13.5px">Clubs are clearing their books before the window closes. Bids for your players are in your inbox.</p></div>${L.map(d=>{const p=G.players[d.pid],t=G.teams[d.tid];return `<div class="msg" style="cursor:default"><span class="lw">${crest(t)}</span><span style="flex:1;min-width:0"><b>${esc(pname(p))}</b><small style="display:block">${p.pos} \u00b7 ${p.age} \u00b7 OVR ${ovrTxt(p)} \u00b7 ${esc(t.name)}</small><small style="display:block">Fee ${eur(d.fee)} \u00b7 normally ${eur(askPrice(p))}</small></span><button class="btn sm p" data-act="ddbuy:${d.pid}">Talk to him</button></div>`;}).join('')||'<div class="sec mut">No deals left.</div>'}`)}</div>`;}
function derbyBar(f){const D=(G.dby||{})[derbyKey(f.h,f.a)];return `<div class="sec" style="padding-block:6px"><p style="font-size:13.5px"><span class="pill r">${esc(derbyOf(f.h,f.a))}</span> Win or loss counts double${f.h===G.user&&!f.neutral?', crowd +30%':''}${D?` \u00b7 your record ${D.w}\u2013${D.l}`:''}</p></div>`;}
function preCard(){if(!preOn())return '';const P=G.pre,U=G.user,ed=preCanEdit(),T=preT(),dd=d=>new Date(G.season,8,d).toLocaleDateString('en-GB',{day:'2-digit',month:'short'});
  const row=(g,i)=>{const r=P.res[i],home=g.h===U,o=G.teams[home?g.a:g.h],cur=i===P.i;return `<div class="msg pre-row" style="cursor:default${cur?';background:var(--soft)':''}"><span class="lw">${crest(o)}</span><span style="flex:1;min-width:0"><b>${home?'':'@ '}${esc(o.name)}</b><small style="display:block">${dd(g.d)} \u00b7 ${esc(preLabel(g))}${g.neutral?' \u00b7 '+esc(T?T.city:''):home?' \u00b7 home':' \u00b7 away'}</small>${r?`<small style="display:block"><b>${r.h===U?r.hs:r.as}\u2013${r.h===U?r.as:r.hs}</b> ${(r.h===U)===(r.hs>r.as)?'<span class="pill g">W</span>':'<span class="pill r">L</span>'}</small>`:''}</span>${ed&&g.t==='fr'?`<span class="btns pre-btn" style="flex-wrap:nowrap"><button class="btn sm" data-act="preswap:${i}">Change</button><button class="btn sm" data-act="prehome:${i}">${home?'Away':'Home'}</button><button class="btn sm" data-act="prerm:${i}">\u2715</button></span>`:''}</div>`;};
  const tours=P.tours.map((x,k)=>`<div class="msg" style="cursor:default;${P.tour===k?'outline:2px solid var(--or);':''}"><span style="flex:1;min-width:0"><b>${esc(x.name)}</b><small style="display:block">${esc(x.city)} \u00b7 24\u201326 Sep \u00b7 ${x.teams.slice(1).map(i=>esc(G.teams[i].name)).join(', ')}</small><small style="display:block">Entry fee ${eur(x.fee)} \u00b7 winner ${eur(x.prize)}</small></span>${ed?`<button class="btn sm ${P.tour===k?'p':''}" data-act="pretour:${k}">${P.tour===k?'Selected':'Accept'}</button>`:''}</div>`).join('');
  const nba=isNBA(G.teams[U]),gl=G.teams[U].dom==='GL';
  const intro=nba?'Our NBA preseason: four exhibition games before the regular season.':gl?'Two exhibition games against teams from our region before the Tip-Off Tournament.':ed?'Plan the summer: up to four friendlies and one sponsored tournament. Pre-season games do not count for any table or for player stats, cost less energy and give young players minutes. Season tickets and arena naming rights are in Finances.':'Our pre-season schedule.';
  return card('Pre-season',`<div class="sec"><p class="mut" style="font-size:13.5px">${intro}</p></div>${P.games.map(row).join('')||'<div class="sec mut">No friendlies planned.</div>'}
    ${ed&&P.games.filter(g=>g.t==='fr').length<4?'<div class="sec"><button class="btn sm" data-act="preadd">+ Add friendly</button></div>':''}
    ${P.tours.length?`<div class="sec"><h4 style="margin:0">Tournament invitations</h4></div>${tours}${ed?`<div class="sec"><button class="btn sm ${P.tour==null?'p':''}" data-act="pretour:-1">No tournament</button></div>`:''}`:''}
    ${T&&T.champ!=null?`<div class="sec"><span class="pill ${T.champ===U?'g':'k'}">${esc(T.name)}: ${esc(G.teams[T.champ].name)}</span></div>`:''}
    <div class="sec"><div class="btns"><button class="btn p" data-act="continue">${P.i===0&&ed?'Start pre-season':'Next game'}</button><button class="btn" data-act="preskip">Skip pre-season</button></div></div>`);}
// which inbox messages still wait for a decision
function ibNeeds(m){if(!m||!m.act)return false;const t=m.type;
  if(t==='offer'||t==='sheet'||t==='trade'||t==='spoach'||t==='exjob')return !m.done;
  if(t==='midjob')return !m.done&&(m.act.until==null||m.act.until>=G.day);
  if(t==='job')return !m.done&&seasonOver();
  if(t==='room')return !!roomSync().row&&m===G.inbox.find(x=>x.type==='room');
  if(t==='contracts')return expiring().length>0&&m===G.inbox.find(x=>x.type==='contracts');
  if(t==='treq'){const p=G.players[m.act.pid];return !m.done&&!!p&&treqOpen(p);}
  if(t==='media'){const r=m.act.rid!=null&&(G.rum||[]).find(x=>x.id===m.act.rid);return !m.done&&!!r&&r.st==='open';}
  if(t==='nilk'){const p=G.players[m.act.pid];return !m.done&&!!(p&&p.nk&&p.nk.st==='open');}
  if(t==='retire'){const q=G.players[m.act.pid];return !m.done&&!!q&&q.tid===G.user&&q.retAt===G.season;}
  return false;}
function todoHTML(){let bids='',press='',rum='';
  const nb=G.inbox.filter(m=>m.type==='offer'&&ibNeeds(m));
  if(nb.length){const p=G.players[nb[0].act.pid];bids=`<section class="ct-c"><div><small>Transfer bids · ${nb.length} open</small><b>${nb.length===1&&p?`${esc(nb[0].from)} bid for ${esc(sname(p))}`:`${nb.length} bids for your players`}</b></div><button data-act="${nb.length===1?`msg:${nb[0].id}`:'ibcat:todo'}">${nb.length===1?'Open bid':'Open inbox'}</button></section>`;}
  const Q=pressNow();
  if(Q){const live=G.prS&&G.prS.key===Q.key&&!G.prS.over,opp=Q.type==='pre'?G.teams[Q.f.h===G.user?Q.f.a:Q.f.h]:null;
    const lead=Q.type==='pre'?`Before ${opp?esc(opp.name):'the game'}`:Q.type==='post'?esc(Q.why||'After the game'):'Media day';
    press=`<section class="ct-c todo-pc"><span class="todo-mic">${MICSVG}</span><div><small>Press conference</small><b>${lead}</b></div><button data-act="prsopen">${live?'Back to press room':'Enter press room'}</button><button class="mj-n" data-act="pressskip">Send assistant</button></section>`;}
  rum=(G.rum||[]).filter(r=>G.players[r.pid]).slice(-6).reverse().filter(r=>r.st==='open').map(r=>`<section class="ct-c mj"><span class="mj-cr">${crest(G.teams[r.tid])}</span><div><small>Rumour · the press wants an answer</small><b>${esc(r.hd)}</b></div><button data-act="rumr:${r.id}:nfs">Not for sale</button><button class="mj-n" data-act="rumr:${r.id}:price">Has a price</button><button class="mj-n" data-act="rumr:${r.id}:quiet">No comment</button></section>`).join('');
  const hh=dpCard()+shortAlert()+roomAlert()+protestCard()+midJobCard()+spCard()+treqCard()+bids+press+rum+retCard()+ctCard()+ntOfferCard();
  if(!hh)return '';const n=(hh.match(/<section /g)||[]).length;
  return `<section class="todo" aria-label="To do"><header><b>To do</b><em>${n}</em><span>${n===1?'One decision is':'Decisions are'} waiting for you</span></header><div class="todo-g${UI.todoAll?' all':''}">${hh}</div>${n>3?`<button class="todo-more${n>6?' d':''}" data-act="todoall">${UI.todoAll?'Show fewer':`Show all ${n}`}</button>`:''}</section>`;}
function homeHTML(){return todoHTML()+`<div class="g-home"><div class="stack">${preCard()}${nextMatchCard()}${isCol(G.teams[G.user])?nilHome()+ncBracketCard()+apCard():''}${fixturesCard()}${resultsCard()}${rumourCard()}${feedCard()}</div><div class="stack">${pokCard()}${standingsCard()}</div><div class="stack">${inboxCard()}${spotlightCard()}${boardCard()}</div></div>`;}
function h2hGames(a,b,kind){return (isFecK(kind)&&G.fec?G.fec.res:isBclK(kind)&&G.bcl?G.bcl.res:isEcK(kind)&&G.ec?G.ec.res:isNlK(kind)&&nlOf(a)?nlOf(a).res:isBihK(kind)&&G.bih?G.bih.res:isKlsK(kind)&&G.kls?G.kls.res:isD2K(kind)&&G.dom2?G.dom2.res:isDomK(kind)&&G.dom?G.dom.res:G.res).filter(r=>(r[0]===a&&r[1]===b)||(r[0]===b&&r[1]===a));}
function h2hLine(a,b,kind){const g=(isFecK(kind)&&G.fec?G.fec.res:isBclK(kind)&&G.bcl?G.bcl.res:isEcK(kind)&&G.ec?G.ec.res:isNlK(kind)&&nlOf(a)?nlOf(a).res:isBihK(kind)&&G.bih?G.bih.res:isKlsK(kind)&&G.kls?G.kls.res:isD2K(kind)&&G.dom2?G.dom2.res:isDomK(kind)&&G.dom?G.dom.res:G.res).filter(r=>(r[0]===a&&r[1]===b)||(r[0]===b&&r[1]===a));if(!g.length)return 'First meeting this season';return g.map(r=>`${G.teams[r[0]].short} ${r[2]}\u2013${r[3]} ${G.teams[r[1]].short}`).join(' \u00b7 ');}
function tacLine(tac){return `${TAC.pace.find(x=>x.v===tac.pace).l} pace \u00b7 ${TAC.focus.find(x=>x.v===tac.focus).l} offense \u00b7 ${TAC.def.find(x=>x.v===tac.def).l}`;}
function fxContext(f){if(f.kind==='pre')return preLabel(f.pre);if(f.ref==='aq'&&G.aq){const A=G.aq;return `Promotion/relegation series \u00b7 ${G.teams[A.aba].short} ${A.wa}\u2013${A.wb} ${G.teams[A.a2].short} \u00b7 best of 3 for a place in the ABA League`;}const D=G.dom,D2=G.dom2,K=G.kls,B=G.bih;if(f.kind==='fec')return f.st==='r2'?`Europe Cup Second Round \u00b7 Group ${fecGroupOf(f.h,true)}`:`Europe Cup Group ${fecGroupOf(f.h)} \u00b7 regular season`;if(f.kind==='fecpo'){const F=G.fec,s=F.po.ser[f.ref];return `Europe Cup ${FECSTAGE[F.po.stage].toLowerCase()} \u00b7 ${s.n===0?'first leg':`second leg \u00b7 aggregate ${G.teams[s.hi].short} ${s.ph}\u2013${s.pl} ${G.teams[s.lo].short}`}`;}if(f.kind==='bcl'){const B=G.bcl;return f.st==='r16'?`Champions League Round of 16 \u00b7 Group ${bclGroupOf(f.h,true)}`:`Champions League Group ${bclGroupOf(f.h)} \u00b7 regular season`;}if(f.kind==='bclpo'){const B=G.bcl,s=B.po.ser[f.ref];return s.need>1?`Champions League ${BCLSTAGE[B.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`:`Champions League ${BCLSTAGE[B.po.stage]} \u00b7 neutral court`;}if(f.kind==='ec'){const E=G.ec;return `EuroCup Group ${ecGroupOf(f.h)} \u00b7 ${E.rounds.length-E.round-1} group rounds left after this one`;}if(f.kind==='ecpo'){const E=G.ec,s=E.po.ser[f.ref];return `EuroCup ${ECSTAGE[E.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`;}if(f.kind==='nl'){const L=G.nl[f.lg],C=NLCFG[L.code];return `${L.groups&&G.teams[f.h].grp?`${C.short} ${G.teams[f.h].grp} \u00b7 `:''}${L.sched.length-L.round-1} ${C.short} rounds left after this one`;}if(f.kind==='nlpo'){const L=G.nl[f.lg],C=NLCFG[L.code],s=L.po.ser[f.ref];return s.agg?`${C.short} ${L.code==='PROA'?'finals':nlStName(L,L.po.stage).toLowerCase()} \u00b7 ${s.n===0?'first leg':`second leg \u00b7 aggregate ${G.teams[s.hi].short} ${s.ph}\u2013${s.pl} ${G.teams[s.lo].short}`}`:s.need>1?`${C.short} ${nlStName(L,L.po.stage).toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of ${s.need*2-1}`:`${C.short} ${nlStName(L,L.po.stage).toLowerCase()} \u00b7 single game`;}if(f.kind==='bihpo'){const s=B.po.ser[f.ref];return s.agg?`Prvenstvo BiH ${BIHSTAGE[B.po.stage].toLowerCase()} \u00b7 two legs on aggregate \u00b7 ${s.n===0?'first leg':`aggregate ${G.teams[s.hi].short} ${s.ph}\u2013${s.pl} ${G.teams[s.lo].short}`}`:`Prvenstvo BiH final \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`;}if(f.kind==='klspo'){const s=K.po.ser[f.ref];return s.need>1?`KLS Super League quarter-final \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`:`KLS ${KLSSTAGE[K.po.stage]} \u00b7 single game \u00b7 neutral venue`;}if(f.kind==='kls')return `${K.sched.length-K.round-1} First League rounds left`;if(f.kind==='bih')return `${B.sched.length-B.round-1} Liga 14 rounds left`;if(f.kind==='d2')return `Group ${dom2GroupOf(f.h)} \u00b7 ${D2.sched.length-D2.round-1} group rounds left after this one`;if(f.kind==='d2po'){const s=D2.po.ser[f.ref];return s.need>1?`ABA League 2 ${DOM2STAGE[D2.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`:'ABA League 2 Play-In \u00b7 single game';}if(f.kind==='dom')return D.top8?`${D.top8.includes(f.h)?'Top 8':'Play-Out'} \u00b7 ${D.sched.length-D.round-1} rounds left after this one`:`${D.groups.A.includes(f.h)?'Group A':'Group B'} \u00b7 ${D.n1-D.round-1} group rounds left after this one`;if(f.kind==='dpo'){const s=D.po.ser[f.ref];return s.need>1?`ABA ${DOMSTAGE[D.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of ${s.need*2-1}`:`ABA ${DOMSTAGE[D.po.stage].toLowerCase()} \u00b7 single game${D.po.stage==='pi1'&&f.ref===0?' \u00b7 the loser gets a second chance':''}`;}if(f.kind==='po'){const s=G.po.qf[f.ref];return `Series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of five`;}if(f.kind==='pi')return 'Single game \u00b7 loser is eliminated';if(f.kind==='f4')return 'Semi-final \u00b7 single game';if(f.kind==='fin')return 'Championship game';return `${G.schedule.length-G.round-1} rounds left after this one`;}
// competition stage plus the step label, without repeating words the label already starts with ("Final Four · Final Four · …")
const kindLine=f=>{if(f.kind==='pre')return preLabel(f.pre);const dn=derbyOf(f.h,f.a);if(dn)return `${dn} \u00b7 ${kindLine0(f)}`;return kindLine0(f);};
const kindLine0=f=>{const k=KINDN[f.kind]||'',l=stepLabel();return k&&!l.startsWith(k)?`${k} \u00b7 ${l}`:l;};
const fxRank=(f,id)=>isFecK(f.kind)?fecRank(id,G.fec.phase!=='reg'&&!!G.fec.g2):isBclK(f.kind)?bclRank(id,G.bcl.phase!=='reg'&&!!G.bcl.g16):isEcK(f.kind)?ecRank(id):isNlK(f.kind)?nlRank(G.nl[f.lg],id):isBihK(f.kind)?bihRank(id):isKlsK(f.kind)?klsRank(id):isD2K(f.kind)?dom2Rank(id):isDomK(f.kind)?domRank(id):rankOf(id);
const fxRec=(f,t)=>isFecK(f.kind)?(r=>`${r[0]}\u2013${r[1]}`)(fecRec(t.id,f.st==='r2')):isBclK(f.kind)?(r=>`${r[0]}\u2013${r[1]}`)(bclRec(t.id,f.st==='r16')):isEcK(f.kind)?(r=>`${r[0]}\u2013${r[1]}`)(ecRec(t.id)):isNlK(f.kind)?(r=>`${r[0]}\u2013${r[1]}`)(nlRec(G.nl[f.lg],t.id)):isBihK(f.kind)?`${t.bw||0}\u2013${t.bl||0}`:isKlsK(f.kind)?`${t.kw||0}\u2013${t.kl||0}`:isDomK(f.kind)?`${t.dw}\u2013${t.dl}`:`${t.w}\u2013${t.l}`;
const clubLg=t=>!t.dom?'EuroLeague':t.dom==='ABA'?'ABA League':t.dom==='ABA2'?'ABA League 2':t.dom==='KLS'?'KLS':t.dom==='BIH'?'Liga BiH':NLCFG[t.dom]?(NLCFG[t.dom].short||NLCFG[t.dom].name):'European';
const rankTxt=(f,id)=>{const r=fxRank(f,id);return r?`${ordn(r)} (${fxRec(f,G.teams[id])})`:`${clubLg(G.teams[id])} club, seeded directly`;};
const compName=f=>f.kind==='pre'?(f.pre&&f.pre.t[0]==='t'&&preT()?preT().name:f.pre&&f.pre.t==='nba'?'NBA Preseason':'Pre-season'):isFecK(f.kind)?'FIBA Europe Cup':isBclK(f.kind)?'Basketball Champions League':isEcK(f.kind)?'BKT EuroCup':isNlK(f.kind)?NLCFG[f.lg].name:isBihK(f.kind)?'Prvenstvo BiH':isKlsK(f.kind)?'Meridianbet KLS':isD2K(f.kind)?'ABA League 2':isDomK(f.kind)?'AdmiralBet ABA League':'Turkish Airlines Euroleague';
function versusHTML(f){const h=G.teams[f.h],a=G.teams[f.a],pre=f.kind==='pre',d=gdate();
  const meta=t=>{const r=!pre&&fxRank(f,t.id);return r?`<b>${ordn(r)}</b> · ${fxRec(f,t)}`:pre?esc(t.city):`${clubLg(t)} club`;};
  const side=t=>`<div class="side click vs-s" data-act="club:${t.id}"><span class="vs-cr">${crest(t)}</span><h4>${apPre(t.id)}${esc(t.name)}</h4><p class="vs-m">${meta(t)}</p>${form(t.form)}</div>`;
  return `<div class="versus vs2${Math.max(h.name.length,a.name.length)<=12?' vs-1l':''}">${side(h)}<div class="vs-mid"><span class="vs-vs">vs</span><b class="vs-t">20:30</b><span class="vs-d">${d.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</span></div>${side(a)}</div>
  <div class="vs-ven">${f.neutral?'Neutral venue':`${esc(h.arena)} · ${h.cap.toLocaleString('en-GB')} seats`}</div>`;}
function probHTML(f){const h=G.teams[f.h],a=G.teams[f.a],wp=winProb(f.h,f.a,f.neutral),hp=Math.round(wp*100);
  return `<div class="prob"><i style="width:${hp}%;background:${lum(h.c1)>.85?h.c2:h.c1}"></i><i style="width:${100-hp}%;background:${lum(a.c1)>.85?a.c2:a.c1}"></i></div><div class="probl"><span>${h.short} ${hp}%</span><span class="mut">Win probability</span><span>${100-hp}% ${a.short}</span></div>`;}
// next match facts as pictures: last meeting, crowd, rest, the five, how they play
