function fixturesCard(){
  const U=G.user,UL=nlUser(),past=G.res.concat(G.dom?G.dom.res:[],G.bih?G.bih.res:[],UL?UL.res:[],G.ec?G.ec.res:[],G.bcl?G.bcl.res:[],G.fec?G.fec.res:[]).filter(r=>r[0]===U||r[1]===U).sort((x,y)=>(x[5]||0)-(y[5]||0)).slice(-2),items=[];
  for(const r of past){const home=r[0]===U,opp=G.teams[home?r[1]:r[0]],won=(home?r[2]>r[3]:r[3]>r[2]);items.push(`<div><small>${isNlK(r[4])&&UL?`${NLCFG[UL.code].short}${r[4]==='nlpo'?' Playoffs':''}`:KINDN[r[4]]}</small><b>${apPre(opp.id)}${esc(opp.name)}</b><span>${home?'H':'A'} \u00b7 ${r[2]}\u2013${r[3]}</span><em class="res ${won?'W':'L'}" style="font-style:normal;background:${won?'var(--g)':'var(--r)'}">${won?'W':'L'}</em></div>`);}
  const nf=userFx();if(nf){const home=nf.h===U;items.push(`<div class="nxt"><small>Next \u00b7 ${stepLabel()}</small><b>${apPre(home?nf.a:nf.h)}${esc(G.teams[home?nf.a:nf.h].name)}</b><span>${nf.neutral?'N':home?'H':'A'} \u00b7 20:30</span></div>`);}
  if(userIsCup()&&userCup()==='fec'&&G.fec.phase==='reg'){const F=G.fec;for(let r=F.round+1;r<F.rounds.length&&items.length<5;r++){const g=F.rounds[r].g.find(x=>x[0]===U||x[1]===U);if(!g)continue;const home=g[0]===U;items.push(`<div><small>Europe Cup \u00b7 Week ${F.rounds[r].r}</small><b>${esc(G.teams[home?g[1]:g[0]].name)}</b><span>${home?'H':'A'}</span></div>`);}}
  else if(userIsCup()&&userCup()==='bcl'&&G.bcl.phase==='reg'){const B=G.bcl;for(let r=B.round+1;r<B.rounds.length&&items.length<5;r++){const g=B.rounds[r].g.find(x=>x[0]===U||x[1]===U);if(!g)continue;const home=g[0]===U;items.push(`<div><small>BCL \u00b7 Week ${B.rounds[r].r}</small><b>${esc(G.teams[home?g[1]:g[0]].name)}</b><span>${home?'H':'A'}</span></div>`);}}
  else if(userIsCup()&&G.ec&&G.ec.phase==='reg'){const E=G.ec;for(let r=E.round+1;r<E.rounds.length&&items.length<5;r++){const g=E.rounds[r].g.find(x=>x[0]===U||x[1]===U);if(!g)continue;const home=g[0]===U;items.push(`<div><small>EuroCup \u00b7 Round ${E.rounds[r].r}</small><b>${esc(G.teams[home?g[1]:g[0]].name)}</b><span>${home?'H':'A'}</span></div>`);}}
  else if(userIsNL()){if(UL.phase==='reg')for(let r=UL.round+1;r<UL.sched.length&&items.length<5;r++){const g=UL.sched[r].find(x=>(x[0]===U||x[1]===U)&&x[0]>=0&&x[1]>=0);if(!g)continue;const home=g[0]===U;items.push(`<div><small>${NLCFG[UL.code].short} \u00b7 Round ${r+1}</small><b>${esc(G.teams[home?g[1]:g[0]].name)}</b><span>${home?'H':'A'}</span></div>`);}}
  else if(userIsKls()&&G.kls.phase==='reg'){const K=G.kls;for(let r=K.round+1;r<K.sched.length&&items.length<5;r++){const g=K.sched[r].find(x=>(x[0]===U||x[1]===U)&&x[0]>=0&&x[1]>=0);if(!g)continue;const home=g[0]===U;items.push(`<div><small>KLS \u00b7 Round ${r+1}</small><b>${esc(G.teams[home?g[1]:g[0]].name)}</b><span>${home?'H':'A'}</span></div>`);}}
  else if(userIsBih()&&G.bih.phase==='reg'){const B=G.bih;for(let r=B.round+1;r<B.sched.length&&items.length<5;r++){const g=B.sched[r].find(x=>(x[0]===U||x[1]===U)&&x[0]>=0&&x[1]>=0);if(!g)continue;const home=g[0]===U;items.push(`<div><small>Liga 14 \u00b7 Round ${r+1}</small><b>${esc(G.teams[home?g[1]:g[0]].name)}</b><span>${home?'H':'A'}</span></div>`);}}
  else if(G.phase==='reg'){const D=domPlaysUser()&&G.dom.phase==='reg'?G.dom:UL&&UL.phase==='reg'?UL:null,dl=D&&D===UL?NLCFG[UL.code].short:'ABA',onD=G.leg==='dom'||G.leg==='nl';const seq=[];
    for(let r=G.round;r<G.schedule.length;r++){if(r>G.round||onD)seq.push(['el',r]);if(D&&r>=D.round&&!(r===D.round&&onD))seq.push(['dom',r]);}
    if(onD)seq.shift();
    for(const [k,r] of seq){if(items.length>=5)break;const sc=k==='el'?G.schedule:D.sched;const g=(sc[r]||[]).find(x=>(x[0]===U||x[1]===U)&&x[0]>=0&&x[1]>=0);if(!g)continue;const home=g[0]===U;items.push(`<div><small>${k==='el'?'EuroLeague':dl} \u00b7 Round ${r+1}</small><b>${esc(G.teams[home?g[1]:g[0]].name)}</b><span>${home?'H':'A'}</span></div>`);}}
  if(!items.length)return '';
  return card('Fixtures & results',`<div class="fx">${items.join('')}</div>`,lnk('tab:comp','Full schedule'));}
function resultsCard(){const L=G.lastResults;if(!L)return '';
  return card(`Results \u00b7 ${L.label}`,`<div class="rg">${L.list.map(r=>{const H=G.teams[r.h],A=G.teams[r.a],hw=r.hs>r.as;const me=x=>x===G.user?' me':'';return `<div><span class="tm click${hw?' w':''}${me(r.h)}" data-act="club:${r.h}">${mini(H)}<span class="nm">${esc(H.name)}</span></span><span class="sc">${r.hs}\u2013${r.as}${r.ot?' OT':''}</span><span class="tm r click${hw?'':' w'}${me(r.a)}" data-act="club:${r.a}"><span class="nm">${esc(A.name)}</span>${mini(A)}</span></div>`;}).join('')}</div>`);}
function standingsRows(compact){return standings().map((t,i)=>`<tr class="click ${t.id===G.user?'me':i<6?'z1':i<10?'z2':''}" data-act="club:${t.id}"><td class="rk">${i+1}</td><td>${mini(t)}${esc(compact?t.name:t.name)}</td><td class="n">${t.w}</td><td class="n">${t.l}</td>${compact?'':`<td class="n">${t.pf}</td><td class="n">${t.pa}</td>`}<td class="n">${t.pf-t.pa>0?'+':''}${t.pf-t.pa}</td><td>${form(t.form.slice(compact?-3:-5))}</td></tr>`).join('');}
