  ec:()=>{const g=ecGroupOf(G.user);return card(`EuroCup \u00b7 Group ${g}`,ecTableHTML(g,true)+`<div class="cb mut" style="font-size:12.5px"><span class="pill g">1\u20134</span> playoffs (Eighthfinals)</div>`,`<button class="lnk" data-act="comp:ec">All groups \u203a</button>`);},
  nl:()=>{const L=nlUser(),T=nlTables(L).find(x=>x.ids.includes(G.user))||nlTables(L)[0];return card(T.name,`${nlTableHTML(L,T,true)}<div class="cb mut" style="font-size:12.5px">${nlLegend(L)}</div>`,`<button class="lnk" data-act="comp:nl${L.code}">Full table \u203a</button>`);},
