  const closed=G.phase!=='reg';let list,cols;
  const posf=p=>UI.trPos==='ALL'||p.pos===UI.trPos;
  const q=(UI.trQ||'').trim().toLowerCase(),norm=x=>x.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),qn=norm(q),searching=qn.length>=2&&UI.tr!=='mine'&&UI.tr!=='loans';
  if(searching){list=Object.values(G.players).filter(p=>p.tid!==G.user&&!p.ntOnly&&p.yth==null&&!p.prospect&&!(p.loan&&p.loan.dev)&&posf(p)&&(norm(pname(p)).includes(qn)||(p.tid!=null&&(norm(G.teams[p.tid].name).includes(qn)||norm(G.teams[p.tid].short)===qn)))).sort((a,b)=>b.o-a.o);}
  else if(UI.tr==='market'){const lg=UI.trLg||'ALL';list=G.teams.filter(t=>t.id!==G.user&&t.dom!=='GONE'&&t.dom!=='FOUND'&&(lg==='ALL'||trLgKey(t)===lg)).flatMap(t=>roster(t.id)).filter(p=>!p.loan&&posf(p));}
  else if(UI.tr==='fa'){const room=G.fin.wageBudget-wageBill(G.user);list=G.fa.map(i=>G.players[i]).filter(p=>p&&!p.prospect&&(!COL||p.portal)).filter(posf).filter(p=>!UI.faFit||demand(p)<=room).sort((a,b)=>(userNBA()?(!!b.nfa-!!a.nfa):0)||b.o-a.o);}
  else if(UI.tr==='watch'){list=Object.keys(G.watch||{}).map(i=>G.players[i]).filter(p=>p&&posf(p));}
  else if(UI.tr==='loans'){list=loanMarket().map(e=>G.players[e.pid]).filter(p=>p&&posf(p));}
  else list=G.listed.map(i=>G.players[i]).filter(Boolean);
  const room0=G.fin.wageBudget-wageBill(G.user),nbaU=userNBA(),canFit=UI.tr==='market'&&!searching&&!nbaU;let fit=canFit?(UI.trFit||'fit'):'all',fitFell=false;
  if(canFit&&fit!=='all'){const av=list.filter(p=>!nbaLocked(p)&&!justJoined(p));
    if(fit==='fit'){const af=av.filter(p=>demand(p)<=room0&&askPrice(p)<=G.fin.bal);if(af.length)list=af;else{list=av;fit='avail';fitFell=true;}}else list=av;}
  const sk=UI.trSort||'o',sd=UI.trDir||TRDIR[sk]||-1;
  if(UI.trSort||UI.tr==='market'||UI.tr==='watch'||searching){const f={o:ovrEst,pot:potEst,age:p=>p.age,wage:demand,price:p=>p.tid==null?0:UI.tr==='mine'?value(p):askPrice(p)}[sk];
    if(sk==='name')list=list.slice().sort((x,y)=>sd*pname(x).localeCompare(pname(y)));
    else if(f){const V=new Map(list.map(p=>[p,f(p)]));list=list.slice().sort((x,y)=>sd*(V.get(x)-V.get(y))||y.o-x.o);}}
  const PG=25,total=list.length,pages=Math.max(1,Math.ceil(total/PG)),pg=clamp(UI.trPg||0,0,pages-1);list=list.slice(pg*PG,pg*PG+PG);
  const sh=(k,l,c)=>`<th class="${c||''}${sk===k?' on':''}"${sk===k?` aria-sort="${sd>0?'ascending':'descending'}"`:''}><button class="trx-s" data-act="trsort:${k}">${l}${sk===k?(sd>0?' ↑':' ↓'):''}</button></th>`;
