  const pager=total>PG?`<div class="trx-pg"><span>${pg*PG+1}–${Math.min(total,pg*PG+PG)} of ${total.toLocaleString('en-GB')}</span><div class="btns"><button class="btn sm" data-act="trpg:${pg-1}" ${pg?'':'disabled'}>‹ Previous</button><span>Page ${pg+1} of ${pages}</span><button class="btn sm" data-act="trpg:${pg+1}" ${pg<pages-1?'':'disabled'}>Next ›</button></div></div>`:'';
  const rows=UI.tr==='loans'?list.map(p=>{const e=loanEntry(p.id),t=G.teams[p.tid];return `<tr class="click" data-act="prof:${p.id}"><td>${nm(p)}</td><td>${p.pos}</td><td class="n">${p.age}</td><td class="hm">${p.nat}</td><td>${mini(t)}${esc(t.short)}</td><td class="n">${ovb(ovrEst(p))}</td><td class="n mut hm">${potTxt(p)}</td><td><span class="pill ${e.why==='dev'?'g':e.why==='cut'?'o':'k'}">${LOANWHY[e.why]}</span>${e.buy?` <span class="pill ${e.buy.type==='ob'?'r':'b'}">${e.buy.type==='ob'?'Obligation':'Option'} ${eur(e.buy.fee)}</span>`:''}</td><td class="r">${e.pct}% \u00b7 ${eur(loanInCost(p,e.pct))}</td><td class="r">${e.fee?eur(e.fee):'\u2013'}</td><td class="r"><button class="btn sm p" data-act="loanin:${p.id}" ${closed?'disabled':''}>Request loan</button></td></tr>`;}).join(''):list.map(p=>{const t=p.tid!=null?G.teams[p.tid]:null;const fa=p.tid==null,lock=nbaLocked(p),far=!fa&&!lock&&UI.tr!=='mine'&&askPrice(p)>G.fin.bal,price=lock?'\u2013':searching?(fa?'Free':eur(askPrice(p))):UI.tr==='market'?eur(askPrice(p)):UI.tr==='fa'?'Free':UI.tr==='watch'?(fa?'Free':eur(askPrice(p))):eur(value(p));
    const btn=UI.tr==='mine'?`<button class="btn sm" data-act="list:${p.id}">Unlist</button>`:nbaLocked(p)?(colLock(p)?`<span class="pill k" title="${esc(colLock(p))}">${p.tid!=null?(isCol(G.teams[p.tid])?'College':isNBA(G.teams[p.tid])?'NBA':'Pro'):p.portal?'Portal':'Pro'}</span>`:`<span class="pill k" title="Under NBA contract">NBA contract</span>`):userNBA()&&p.tid!=null&&isNBA(G.teams[p.tid])&&!justJoined(p)?`<button class="btn sm p" data-act="trade:${p.id}">Trade</button>`:justJoined(p)?`<span class="pill k" title="Joined ${esc(G.teams[p.tid].name)} this season">Just signed</span>`:G.faBid&&G.faBid[p.id]?`<span class="pill o">Deciding · ${G.faBid[p.id].left}d</span>`:`<button class="btn sm p" data-act="offer:${p.id}" ${closed?'disabled':''}>${(searching?fa:UI.tr==='fa')?'Sign':'Offer'}</button>`;
    return `<tr class="click" data-act="prof:${p.id}"><td>${nm(p)}</td><td>${p.pos}</td><td class="n">${p.age}</td><td class="hm">${p.nat}</td><td>${t?mini(t)+esc(t.short):`<span class="mut">${p.nfa?`<span class="pill ${p.nfa.rfa?'o':'g'}">${p.nfa.rfa?'RFA':'UFA'}</span> `:''}Free agent${p.last?` \u00b7 ex ${esc(p.last)}`:''}${p.nfa&&p.nfa.from===G.user?' \u00b7 Bird rights':''}</span>`}</td><td class="n">${ovb(ovrEst(p))}</td><td class="n mut hm">${potTxt(p)}</td><td class="r${far?' neg':''}">${price}${clauseOf(p)&&!userNBA()?`<small class="mut" style="display:block;white-space:nowrap">Clause ${eur(clauseOf(p))}</small>`:''}</td><td class="r${!lock&&UI.tr!=='mine'&&demand(p)>room0?' neg':''}">${eur(demand(p))}${p.tid==null?faTag(p):''}</td><td class="r">${btn}</td></tr>`;}).join('');
  const tabs=`<div class="seg">${(COL?[['rec','Recruiting'],['fa',`Transfer portal (${G.fa.filter(i=>G.players[i]&&G.players[i].portal).length})`],['watch',`Watchlist (${Object.keys(G.watch||{}).length})`]]:[['market','Transfer market'],['loans','Loan market'],['fa','Free agents'],['mine',`Your list (${G.listed.length})`]].concat(userNBA()?[['gl','G League']]:[['watch',`Watchlist (${Object.keys(G.watch||{}).length})`]])).map(([k,l])=>`<button class="${UI.tr===k?'on':''}" data-act="trtab:${k}">${l}</button>`).join('')}</div>`;
  const PN={ALL:'All positions',PG:'Point guards',SG:'Shooting guards',SF:'Small forwards',PF:'Power forwards',C:'Centers'};
  const pos=`<div style="display:flex;flex-direction:column;gap:4px"><span class="lbl">Position</span><div class="seg">${['ALL',...POS].map(k=>`<button class="${(UI.trPos||'ALL')===k?'on':''}" data-act="trpos:${k}" title="${PN[k]}">${k==='ALL'?'All':k}</button>`).join('')}</div></div>`;
  const srt=`<div style="display:flex;flex-direction:column;gap:4px"><span class="lbl">Sort by</span><div class="seg">${[['o','Rating'],['pot','Potential'],['age','Youngest'],['wage','Lowest wage']].map(([k,l])=>`<button class="${(UI.trSort||'o')===k?'on':''}" data-act="trsort:${k}">${l}</button>`).join('')}</div></div>`;
  const room=G.fin.wageBudget-wageBill(G.user);
