  roleline(){roleLineup();toast('Squad order set by roles');render();},
  glup(id,k){const er=glCallUp(+id,k);toast(er||'Player called up');render();},
  tenk(id,k){const er=tenKeep(+id,k);if(er)toast(er);render();},
  twconv(id){const er=twConvert(+id);toast(er||'Standard contract signed');render();},
  fanact(k){const er=fanAct(k);if(er)toast(er);render();},
  boardtalk(){UI.modal={kind:'board',res:null,w:'tr'};render();},
