  mentorset(id){const M=UI.modal,e=setMentor(M.pid,+id);if(e){M.res=e;render();return;}UI.modal=null;render();toast('Mentor assigned');},
  mentorend(id){endMentor(+id);UI.modal=null;render();toast('Mentoring ended');},
  playlive(){if(squadShort()){UI.modal={kind:'short'};render();return;}beginMatch(true);},playquick(){if(squadShort()){UI.modal={kind:'short'};render();return;}beginMatch(false);},
