  negsign(){const M=UI.modal,st=G.staffFA.find(x=>x.id===M.n.sid);const e=negSign(st,M.n);if(e){M.err=e;render();return;}UI.modal=null;render();toast(`${st.f} ${st.l} joins your staff`);},
