function ntFill5(){if(!G||G.ntFillV5===1)return;G.ntFillV5=1;const all=Object.values(G.players);
  for(const [f,l,c,pos,dob,ht,club,key,o0,col] of NT_EXTRA5){if(all.some(p=>ntKy(p.l)===ntKy(l)&&ntKy(p.f)===ntKy(f)))continue;
    const by=+dob.slice(0,4),bm=+dob.slice(5,7),age=G.season-by-(bm>=10?1:0),o=clamp(o0+rnd(-2,2),40,80),p=genPlayer(o,pos,c,age);p.f=f;p.l=l;p.nat=c;p.ht=ht;p.real=1;
    for(let i=0;i<14&&p.o!==o;i++){const d=o>p.o?1:-1;for(const k of ATTR)p.a[k]=clamp(p.a[k]+d,25,99);upd(p);}p.pot=Math.max(p.o,p.pot);
    p.ntOnly=1;p.ntClub=club;p.yrs=0;p.sal=0;}}

