const rcIco=r=>r.k?`<span class="rc-pri" title="Most important to him: ${RC_PRI[r.pri]}"><svg viewBox="0 0 24 24">${RC_IC[r.pri]}</svg></span>`:`<span class="rc-pri q" title="Contact him to learn what matters most to him">?</span>`;
const rcStars=n=>`<span class="rc-st" title="${n}-star prospect">${'<i></i>'.repeat(n)}${'<i class="o"></i>'.repeat(5-n)}</span>`;
const rcDots=(n,of,cls)=>`<span class="rc-dots ${cls||''}">${Array.from({length:of},(_,i)=>`<i class="${i<n?'f':''}"></i>`).join('')}</span>`;
function rcEst(r){const w=[5,3,0][r.k],o=clamp(r.o+(r.k<2?r.e:0),40,90),p=clamp(r.pot+(r.k<2?r.ep:0),45,97);const R2=(c,lo,hi)=>`${Math.max(lo,c-w)}–${Math.min(hi,c+w)}`;return w?`${R2(o,40,90)}<small>POT ${R2(p,45,99)}</small>`:`${r.o}<small>POT ${r.pot}</small>`;}
function rcTabs(){const n=G.fa.filter(i=>G.players[i]&&G.players[i].portal).length;
  return `<div class="seg">${[['rec','Recruiting'],['fa',pwOpen()?`Transfer portal · open (${n})`:'Transfer portal'],['watch',`Watchlist (${Object.keys(G.watch||{}).length})`]].map(([k,l])=>`<button class="${UI.tr===k?'on':''}" data-act="trtab:${k}">${l}</button>`).join('')}</div>`;}
function rcPage(){const R=rcEnsure();
  if(!R)return `<div class="stack">${colWaysHTML()}${card('Recruiting',`<div class="sec">${rcTabs()}</div><div class="empty"><p class="mut">This year's class has signed. The next recruiting board opens with the new season.</p></div>`)}</div>`;
  const U=G.user,me=G.teams[U],spots=rcSpots(),cm=R.board.filter(r=>r.c===U&&!r.gone).sort((a,b)=>a.rank-b.rank),f=UI.rcF||'all',pos=UI.trPos||'ALL';
  let L=R.board.filter(r=>!r.gone&&(pos==='ALL'||r.pos===pos));
  if(f==='off')L=L.filter(r=>r.off[U]);else if(f==='open')L=L.filter(r=>r.c==null);else if(f==='near'){const g=rcReg(rcState(me));L=L.filter(r=>r.st&&rcReg(r.st)===g);}
  if(UI.rcS==='int')L=L.slice().sort((a,b)=>(b.i[U]||0)-(a.i[U]||0)||a.rank-b.rank);
  const PG=20,total=L.length,pages=Math.max(1,Math.ceil(total/PG)),pg=clamp(UI.rcPg||0,0,pages-1);L=L.slice(pg*PG,pg*PG+PG);
  const next=!R.early?`Early signing day <b>12 Nov</b>`:`Spring signing <b>after the season</b>`;
  const head=`<div class="rc-head">
    <div class="rc-k"><span class="lbl">Class of ${G.season+1}</span><b>${cm.length} committed</b>${(()=>{const C=rcClassRanks();return C&&cm.length?`<small>Class rank No. ${C.rk[U]} of ${C.n}</small>`:'';})()}</div>
    <div class="rc-k"><span class="lbl">Scholarships</span>${rcDots(cm.length,spots,'g')}<small>${cm.length}/${spots} · ${rcOffers(R)}/${rcMaxOff()} offers out</small></div>
    <div class="rc-k"><span class="lbl">Contacts this week</span>${rcDots(R.calls,RC_CALLS)}<small>${R.calls} left · reset each week</small></div>
    <div class="rc-k"><span class="lbl">Campus visits</span>${rcDots(R.vis,RC_VIS,'o')}<small>${R.vis} of ${RC_VIS} left</small></div>
    <div class="rc-k"><span class="lbl">Next</span><span class="rc-nx">${next}</span></div></div>`;
  const cls=cm.length?`<div class="rc-cls">${cm.map(r=>`<div class="rc-c ${r.sg?'sg':''}"><span class="rc-av">${r.pos}</span><div><b>${esc(rcName(r))}</b>${rcStars(r.stars)}<span>${r.sg?'Signed':'Committed'} · No. ${r.rank}</span></div></div>`).join('')}</div>`:`<p class="mut rc-none">No commitments yet. Offer scholarships, call prospects and bring them on campus.</p>`;
  const flt=`<div class="rc-f"><div class="seg">${[['all','All'],['off','Offered'],['open','Uncommitted'],['near','Our region']].map(([k,l])=>`<button class="${f===k?'on':''}" data-act="rcf:${k}">${l}</button>`).join('')}</div>
    <div class="seg">${['ALL',...POS].map(k=>`<button class="${pos===k?'on':''}" data-act="trpos:${k}">${k==='ALL'?'All':k}</button>`).join('')}</div>
    <div class="seg">${[['rank','Rank'],['int','Interest']].map(([k,l])=>`<button class="${(UI.rcS||'rank')===k?'on':''}" data-act="rcs:${k}">${l}</button>`).join('')}</div></div>`;
  const row=r=>{const v=Math.round(r.i[U]||0),ld=rcLead(r),lead=ld[0]&&ld[0].id===U,top=ld.slice(0,3),cT=r.c!=null?G.teams[r.c]:null;
    const st=r.sg?`<span class="pill ${r.c===U?'g':'k'}">${r.c===U?'Signed with us':`Signed · ${esc(cT.short||cT.name)}`}</span>`:r.c===U?`<span class="pill g">Committed to us</span>`:cT?`<span class="pill o rc-cm">${crest(cT,'mini')} Committed</span>`:'';
    const acts=r.sg?'':`<button class="btn sm ${r.off[U]?'':'p'}" data-act="rcoff:${r.id}">${r.off[U]?'Pull offer':'Offer'}</button><button class="btn sm" data-act="rccall:${r.id}" ${R.calls<=0||R.called[r.id]?'disabled':''}>${R.called[r.id]?'Called':'Call'}</button><button class="btn sm" data-act="rcvis:${r.id}" ${!r.off[U]||r.vis||R.vis<=0?'disabled':''} title="${!r.off[U]?'Offer a scholarship first':r.vis?'He has visited':'Official campus visit'}">${r.vis?'Visited':'Visit'}</button>`;
    return `<div class="rc-row ${r.c===U?'mine':''}"><span class="rc-rk">${r.rank}</span>
      <div class="rc-n"><span class="rc-av">${r.pos}</span><div><b>${esc(rcName(r))}</b>${rcStars(r.stars)}<span class="rc-m">${Math.floor(r.ht/30.48)}'${Math.round(r.ht/2.54%12)}" · ${esc(rcHome(r))} ${rcIco(r)}</span></div></div>
      <div class="rc-e" title="Scouted rating and potential${r.k<2?' (call or visit to scout him better)':''}">${rcEst(r)}</div>
      <div class="rc-i" title="His interest in us"><div class="rc-bar"><i class="${lead?'lead':''}" style="width:${v}%"></i></div><b>${v}</b>${r.off[U]?'<span class="rc-of">Offered</span>':''}</div>
      <div class="rc-ld" title="Schools in the lead">${top.map(x=>`<span class="${x.id===U?'me':''}">${crest(G.teams[x.id],'mini')}<small>${Math.round(x.v)}</small></span>`).join('')}</div>
      <div class="rc-x">${st}${acts}</div></div>`;};
  const pager=total>PG?`<div class="trx-pg"><span>${pg*PG+1}–${Math.min(total,pg*PG+PG)} of ${total}</span><div class="btns"><button class="btn sm" data-act="rcpg:${pg-1}" ${pg?'':'disabled'}>‹ Previous</button><span>Page ${pg+1} of ${pages}</span><button class="btn sm" data-act="rcpg:${pg+1}" ${pg<pages-1?'':'disabled'}>Next ›</button></div></div>`:'';
  return `<div class="stack">${colWaysHTML()}${card('Recruiting',`<div class="sec">${rcTabs()}</div>${head}<div class="sec rc-sec"><span class="lbl">Our class</span>${cls}</div>${flt}
    <div class="rc-list"><div class="rc-row rc-hd"><span>#</span><span>Prospect</span><span>Scouted</span><span>Interest in us</span><span>Leaders</span><span></span></div>${L.map(row).join('')||'<p class="mut" style="padding:16px">No prospects match this filter.</p>'}</div>${pager}`)}</div>`;}
Object.assign(ACT,{
  rcoff(id){toast(rcOffer(id));save();render();},rccall(id){toast(rcCall(id));save();render();},rcvis(id){toast(rcVisit(id));save();render();},
  rcf(k){UI.rcF=k;UI.rcPg=0;render();},rcs(k){UI.rcS=k;UI.rcPg=0;render();},rcpg(n){UI.rcPg=+n;render();}});

/* ===================== Transfer portal window page ===================== */
function pwPage(){const F=G.pw,U=G.user,P=pwPool(),pos=UI.trPos||'ALL',room=G.fin.wageBudget-wageBill(U),mine=pwMine();
  let L=P.filter(p=>pos==='ALL'||p.pos===pos);if(UI.pwF==='mine')L=L.filter(p=>p.pw.of[U]!=null);
  L.sort((a,b)=>UI.pwS==='day'?a.pw.d-b.pw.d||b.o-a.o:ovrEst(b)-ovrEst(a));
  const PG=20,total=L.length,pages=Math.max(1,Math.ceil(total/PG)),pg=clamp(UI.trPg||0,0,pages-1);L=L.slice(pg*PG,pg*PG+PG);
  const days=Array.from({length:F.len},(_,i)=>`<i class="${i<F.day?'f':i===F.day?'now':''}"><b>${i+1}</b></i>`).join('');
  const head=`<div class="pw-head"><div class="pw-days" title="Day ${F.day+1} of ${F.len}">${days}</div>
    <div class="rc-k"><span class="lbl">NIL room</span><b class="${room<0?'neg':''}">${eur(room)}</b><small>${eur(pwOfferSum())} offered</small></div>
    <div class="rc-k"><span class="lbl">Roster spots</span>${rcDots(mine.length,Math.max(0,pwSpots()),'g')}<small>${G.teams[U].order.length}/${NC_ROST} · ${mine.length} offer${mine.length===1?'':'s'} out</small></div>
    <div class="rc-k"><span class="lbl">Window</span><b>${F.len-F.day} day${F.len-F.day===1?'':'s'} left</b><small>Press Continue to move to the next day</small></div></div>`;
  const flt=`<div class="rc-f"><div class="seg">${[['all',`All (${P.length})`],['mine',`Our offers (${mine.length})`]].map(([k,l])=>`<button class="${(UI.pwF||'all')===k?'on':''}" data-act="pwf:${k}">${l}</button>`).join('')}</div>
    <div class="seg">${['ALL',...POS].map(k=>`<button class="${pos===k?'on':''}" data-act="trpos:${k}">${k==='ALL'?'All':k}</button>`).join('')}</div>
    <div class="seg">${[['o','Rating'],['day','Decision day']].map(([k,l])=>`<button class="${(UI.pwS||'o')===k?'on':''}" data-act="pws:${k}">${l}</button>`).join('')}</div></div>`;
  const row=p=>{const of=Object.keys(p.pw.of).map(Number),oth=of.filter(i=>i!==U),me=p.pw.of[U],from=G.teams.find(t=>t.name===p.last),ask=pwAsk(p),hi=oth.length?Math.max(...oth.map(i=>p.pw.of[i])):0;
    const acts=me!=null?`<span class="pill g">Offered ${eur(me)}</span>${me<r5k(ask*1.25)?`<button class="btn sm" data-act="pwoff:${p.id}:up">Raise to ${eur(r5k(ask*1.25))}</button>`:''}<button class="btn sm" data-act="pwoff:${p.id}:x">Withdraw</button>`
      :`<button class="btn sm p" data-act="pwoff:${p.id}:ask">Offer ${eur(ask)}</button><button class="btn sm" data-act="pwoff:${p.id}:up">Offer ${eur(r5k(ask*1.25))}</button>`;
    return `<div class="rc-row pw-row ${me!=null?'mine':''}"><span class="pw-dd ${p.pw.d<=F.day+1?'soon':''}" title="Decides on day ${p.pw.d}">D${p.pw.d}</span>
      <div class="rc-n"><span class="avatar ph pw-av">${avatarIn(p,p.no)}</span><div><b class="click" data-act="prof:${p.id}">${esc(pname(p))}</b><span class="rc-m">${p.pos} · ${p.age} · ${p.yrs||p.elig||1} yr${(p.yrs||p.elig||1)===1?'':'s'} left · ${from?crest(from,'mini'):''} ${esc(p.last||'')}</span></div></div>
      <div class="rc-e">${ovrEst(p)}<small>POT ${potEst(p)}</small></div>
      <div class="pw-of" title="Programs that made him an offer">${oth.length?`${oth.slice(0,4).map(i=>crest(G.teams[i],'mini')).join('')}<small>${oth.length} offer${oth.length>1?'s':''}</small>`:'<small>No other offers</small>'}</div>
      <div class="pw-ask"><small>Asks</small><b>${eur(ask)}</b></div>
      <div class="rc-x">${acts}</div></div>`;};
  const pager=total>PG?`<div class="trx-pg"><span>${pg*PG+1}–${Math.min(total,pg*PG+PG)} of ${total}</span><div class="btns"><button class="btn sm" data-act="trpg:${pg-1}" ${pg?'':'disabled'}>‹ Previous</button><span>Page ${pg+1} of ${pages}</span><button class="btn sm" data-act="trpg:${pg+1}" ${pg<pages-1?'':'disabled'}>Next ›</button></div></div>`:'';
  return `<div class="stack">${colWaysHTML()}${card('Transfer portal window',`<div class="sec">${rcTabs()}</div>${head}${flt}<div class="rc-list">${L.map(row).join('')||'<p class="mut" style="padding:16px">No players match this filter.</p>'}</div>${pager}`)}</div>`;}
Object.assign(ACT,{pwoff(a){const [id,k]=a.split(':');toast(pwOffer(id,k));save();render();},pwf(k){UI.pwF=k;UI.trPg=0;render();},pws(k){UI.pwS=k;UI.trPg=0;render();}});

/* ===================== Draft decisions card (Home) ===================== */
function dpCard(){if(typeof dpOpen!=='function'||!dpOpen())return '';const F=G.dp;
  const steps=DP_WK.map((l,i)=>`<span class="${i<F.wk?'f':i===F.wk?'now':''}">${l}</span>`).join('');
  const rows=Object.keys(F.pl).map(id=>{const p=G.players[id],e=F.pl[id];if(!p)return '';const c=Math.round(dpChance(e)*100),lean=c>=60?'Leaning towards returning':c>=35?'Undecided':'Leaning towards the NBA';
    const b=(k,l,t)=>`<button class="btn sm ${e[k]?'':'p'}" data-act="dpact:${p.id}:${k}" ${e[k]?'disabled':''} title="${esc(t)}">${e[k]?'✓ ':''}${l}</button>`;
    return `<div class="dp-p"><span class="avatar ph dp-av">${avatarIn(p,p.no)}</span><div class="dp-b"><div class="dp-n"><b class="click" data-act="prof:${p.id}">${esc(pname(p))}</b><span>${p.pos} · ${p.age} · OVR ${p.o} · ${esc(ncClass(p))}</span>${e.fb?`<span class="pill o">${dpProj(e.r)}</span>`:'<span class="pill k" title="Ask the NBA for feedback">Projection ?</span>'}${e.cb?`<span class="pill ${e.cb>0?'r':'g'}">Combine ${e.cb>0?'↑':'↓'}</span>`:''}</div>
      <div class="dp-m"><span>NBA</span><div class="dp-bar"><i style="width:${c}%"></i></div><span>Return</span><b>${c}%</b></div><small class="mut">${lean}</small>
      <div class="btns">${b('fb','NBA feedback','Ask the NBA Undergraduate Advisory Committee where he would be picked')}${b('role','Promise a bigger role','Promise he will be the focus of the offense next season')}${b('nil',`NIL +${eur(dpNil(p))}`,'More NIL money if he returns (from NIL room)')}${b('sup','Back his decision','Tell him you support him either way')}</div></div></div>`;}).join('');
  return `<section class="card dp-card"><div class="dp-h"><div><small>NBA Draft · will he come back?</small><b>${F.len-F.wk} week${F.len-F.wk===1?'':'s'} to the withdrawal deadline</b></div><div class="dp-st">${steps}</div></div>${rows}</section>`;}
Object.assign(ACT,{dpact(a){const [id,k]=a.split(':');toast(dpAct(id,k));save();render();}});

/* ===================== Bracketology (Home, college) ===================== */
function ncBracketCard(){const P=typeof ncProj==='function'?ncProj():null;if(!P)return '';const U=G.user,s=P.s,Q=P.q,nm=i=>esc(G.teams[i].short||G.teams[i].name);
  const st=P.st==='in'?{c:'g',t:`Projected No. ${s.s} seed`,d:`${NCREG[s.r]} Region${P.auto?' · conference leader':''}`}:P.st==='ff'?{c:'o',t:'Last teams in',d:`First Four in Dayton · No. 8 seed line`}:P.st==='out4'?{c:'r',t:'First four out',d:'On the wrong side of the bubble'}:{c:'k',t:'Out of the field',d:'Needs a run or the conference title'};
  const q=(l,w,lo)=>`<div class="br-q"><small>${l}</small><b>${w}–${lo}</b></div>`;
  const bub=(l,L)=>`<div class="br-b"><small>${l}</small>${L.map(i=>`<span class="${i===U?'me':''}" title="${esc(G.teams[i].name)}">${crest(G.teams[i],'mini')}${nm(i)}</span>`).join('')}</div>`;
  return card('Bracketology',`<div class="br"><div class="br-net"><small>NET</small><b>${P.rank}</b><span>of ${G.nl.NCAA.ids.length}</span></div>
    <div class="br-m"><span class="pill ${st.c}">${st.t}</span><span class="br-d">${st.d}</span><div class="br-qs">${q('Quad 1',Q[0],Q[1])}${q('Quad 2',Q[2],Q[3])}${q('Quad 3',Q[4],Q[5])}</div></div></div>
    <div class="br-bb">${bub('Last four in',P.in4)}${bub('First four out',P.out4)}</div>
    <p class="mut br-n">If the season ended today. Seeds follow the NET and Quad 1 wins; conference champions get automatic bids.</p>`);}

/* ===================== AP Top 25 (Home, rank badges) ===================== */
const apPre=id=>{const r=typeof apRank==='function'?apRank(id):0;return r?`<span class="apn" title="AP Top 25">${r}</span>`:'';};
function apCard(){const L=G.nl&&G.nl.NCAA,A=L&&L.ap,U=G.user;if(!A||A.s!==G.season||!A.top.length)return '';
  const row=(id,k)=>{const p=A.prev[id],d=p?p-(k+1):null,r=nlRec(L,id),mv=d==null?(A.wk>1?'<i class="new">New</i>':''):d>0?`<i class="up">▲${d}</i>`:d<0?`<i class="dn">▼${-d}</i>`:'<i class="eq">–</i>';
    return `<div class="ap-r ${id===U?'me':''}" data-act="club:${id}"><b>${k+1}</b>${crest(G.teams[id],'mini')}<span>${esc(G.teams[id].short||G.teams[id].name)}</span><small>${r[0]}–${r[1]}</small>${mv}<em>${A.pts[id]}${k===0?` (${A.fpv})`:''}</em></div>`;};
  const mine=apRank(U),out=!mine&&L.ids.includes(U)?`<p class="mut ap-o">${esc(G.teams[U].name)}: not ranked${A.prev[U]?` (No. ${A.prev[U]} last week)`:''}</p>`:'';
  return card(A.fin?'Final AP Top 25':A.wk===1?'AP Top 25 · Preseason':`AP Top 25 · Week ${A.wk-1}`,`<div class="ap">${A.top.map(row).join('')}</div>${out}`);}


