function bihPh(){if(!G)return;for(const p of Object.values(G.players))if(p.f==='Emir'&&p.l==='Preldzic'&&p.nat==='SLO')p.nat='TUR';else if(p.f==='Karlo'&&p.l==='Matkovic'&&p.nat==='USA')p.nat='CRO';  // played for Türkiye; Eurobasket lists him as Slovenian
  for(const t of G.teams){if(t.dom!=='BIH')continue;for(const p of roster(t.id)){const k=(window.PH_ALT||{})[t.short+'|'+p.f+' '+p.l];if(k)p.phk=k;}}
  if(G.bihHC)return;G.bihHC=1;for(const t of G.teams){const hc=((window.BIH_STAFF||{})[t.short]||[])[0],x=(t.staff||[]).find(s=>s.role==='HC');if(t.dom!=='BIH'||!hc||!x||t.id===G.user)continue;x.f=hc[1];x.l=hc[2];x.nat=hc[3];x.age=G.season-Math.abs(hc[4]);}}

