function tutGo(){if(!tutOn()||G.tut.s<0)return;const st=tutSteps()[G.tut.s];if(!st)return;UI.view='main';UI.modal=null;UI.tab=st.tab;if(G.tut.s===0)G.tut.l.goal=1;}
